// I Samuel — tradução dos originais (versificação: Nova Vulgata)
// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================


window.TEXTOS_SEED["1samuel"][1] = [
{s:"Ana, mãe de Samuel"},
{v:1,t:"Havia um homem de Ramataim-Sofim, da montanha de Efraim, chamado Elcana, filho de Jeroam, filho de Eliú, filho de Tou, filho de Suf, efraimita.",n:"Os livros de Samuel, que eram um só na Bíblia hebraica, contam a passagem de Israel do tempo dos juízes à monarquia: Samuel, o último juiz; Saul, o primeiro rei; Davi, o rei segundo o coração de Deus. A Vulgata antiga chamava-os Primeiro e Segundo dos Reis."},
{v:2,t:"Tinha duas mulheres: uma chamava-se Ana, e a outra, Fenena. Fenena tinha filhos, mas Ana não tinha."},
{v:3,t:"Todos os anos, esse homem subia da sua cidade para adorar e oferecer sacrifícios ao Senhor dos exércitos em Silo; ali estavam os dois filhos de Heli, Ofni e Fineias, sacerdotes do Senhor.",n:"Senhor dos exércitos, Yahweh Sabaot, aparece aqui pela primeira vez na Bíblia, ligado ao santuário de Silo e à arca. Os exércitos são os astros e os anjos, e também as tropas de Israel."},
{v:4,t:"No dia em que Elcana oferecia o sacrifício, dava porções a Fenena, sua mulher, e a todos os filhos e filhas dela;",np:1},
{v:5,t:"mas a Ana dava uma porção escolhida, porque amava Ana, embora o Senhor lhe tivesse fechado o ventre."},
{v:6,t:"A sua rival a afligia duramente, para irritá-la, porque o Senhor lhe tinha fechado o ventre."},
{v:7,t:"Assim acontecia todos os anos: sempre que subiam à casa do Senhor, a outra a irritava; e Ana chorava e não comia."},
{v:8,t:"Elcana, seu marido, disse-lhe: Ana, por que choras? Por que não comes? Por que está triste o teu coração? Não sou eu para ti melhor do que dez filhos?",n:"O amor de Elcana é sincero e um pouco desajeitado: não entende que um marido não substitui um filho."},
{v:9,t:"Depois que comeram e beberam em Silo, Ana levantou-se. O sacerdote Heli estava sentado na cadeira, junto à ombreira do templo do Senhor.",np:1},
{v:10,t:"Ela, com a alma amargurada, orou ao Senhor, chorando muito,"},
{v:11,t:"e fez este voto: Senhor dos exércitos, se olhares para a aflição da tua serva e te lembrares de mim, se não te esqueceres da tua serva e deres à tua serva um filho homem, eu o darei ao Senhor por todos os dias da sua vida, e a navalha não passará pela sua cabeça.",n:"Ana promete um nazireu, como a mãe de Sansão. O Magnificat de Maria ecoará esta oração: olhou para a humildade da sua serva."},
{v:12,t:"Enquanto ela prolongava a sua oração diante do Senhor, Heli observava-lhe a boca."},
{v:13,t:"Ana falava no seu coração; só os lábios se moviam, mas não se ouvia a voz. Heli pensou que ela estivesse embriagada,",n:"Rezava-se em voz alta. A oração silenciosa de Ana é a primeira da Bíblia, e o sacerdote não a compreende."},
{v:14,t:"e disse-lhe: Até quando estarás embriagada? Livra-te do teu vinho!"},
{v:15,t:"Ana respondeu: Não, meu senhor; sou uma mulher angustiada. Não bebi vinho nem bebida fermentada, mas derramava a minha alma diante do Senhor.",n:"Derramar a alma diante de Deus: a expressão dos salmos para a oração de quem sofre."},
{v:16,t:"Não tomes a tua serva por uma mulher perversa; foi pela grandeza da minha dor e da minha aflição que falei até agora."},
{v:17,t:"Heli respondeu: Vai em paz, e o Deus de Israel te conceda o que lhe pediste."},
{v:18,t:"Ela disse: Que a tua serva encontre graça aos teus olhos. E a mulher seguiu o seu caminho e comeu, e o seu rosto não era mais o mesmo."},
{v:19,t:"Levantaram-se cedo e prostraram-se diante do Senhor; depois voltaram para casa, em Ramá. Elcana uniu-se a Ana, sua mulher, e o Senhor lembrou-se dela."},
{v:20,t:"Passado algum tempo, Ana concebeu e deu à luz um filho, e pôs-lhe o nome de Samuel, porque disse: Pedi-o ao Senhor.",np:1,n:"A etimologia popular liga o nome Samuel ao verbo pedir, shaal, que atravessa todo o capítulo; o nome significa, antes, o seu nome é Deus."},
{v:21,t:"Elcana subiu com toda a sua família para oferecer ao Senhor o sacrifício anual e cumprir o seu voto.",np:1},
{v:22,t:"Mas Ana não subiu, porque disse ao marido: Não irei até que o menino seja desmamado; então o levarei, para que seja apresentado diante do Senhor e fique ali para sempre.",n:"O desmame dava-se então por volta dos três anos."},
{v:23,t:"Elcana, seu marido, respondeu-lhe: Faze o que te parecer bem; fica até que o desmames; somente o Senhor cumpra a sua palavra. A mulher ficou e amamentou o filho até desmamá-lo."},
{v:24,t:"Depois de desmamado, levou-o consigo, com um novilho de três anos, um efá de farinha e um odre de vinho, e levou-o à casa do Senhor, em Silo. O menino era ainda muito pequeno."},
{v:25,t:"Imolaram o novilho e apresentaram o menino a Heli."},
{v:26,t:"Ana disse: Com licença, meu senhor! Pela tua vida, meu senhor, eu sou aquela mulher que esteve aqui junto de ti, orando ao Senhor."},
{v:27,t:"Foi por este menino que orei, e o Senhor concedeu-me o que lhe pedi."},
{v:28,t:"Por isso também eu o cedo ao Senhor: por todos os dias da sua vida, ele será cedido ao Senhor. E prostraram-se ali diante do Senhor.",n:"Cedido, à letra pedido: o mesmo verbo do nome de Samuel. Ana devolve a Deus o que lhe pediu."}
];

window.TEXTOS_SEED["1samuel"][2] = [
{s:"O cântico de Ana"},
{v:1,l:["E Ana orou, dizendo:","O meu coração exulta no Senhor,","a minha força se eleva no meu Deus;","a minha boca se abre contra os meus inimigos,","porque me alegro na tua salvação."],n:"O cântico de Ana é o modelo do Magnificat de Maria, que retoma o seu movimento: Deus derruba os poderosos e exalta os humildes. A força, à letra o chifre, é a imagem do vigor do animal que ergue a cabeça."},
{v:2,l:["Não há santo como o Senhor;","não há outro além de ti,","não há rocha como o nosso Deus."]},
{v:3,l:["Não multipliqueis palavras soberbas,","nem saia arrogância da vossa boca,","porque o Senhor é um Deus que sabe tudo, e é ele quem pesa as ações."]},
{v:4,l:["O arco dos poderosos é quebrado,","e os fracos são cingidos de força."]},
{v:5,l:["Os fartos alugam-se por pão,","e os famintos já não passam fome;","a estéril deu à luz sete vezes,","e a mãe de muitos filhos definha."],n:"Sete é o número da plenitude. Ana terá cinco filhos: o cântico canta mais do que a sua história, canta o modo de agir de Deus."},
{v:6,l:["O Senhor dá a morte e dá a vida,","faz descer à morada dos mortos e faz subir de lá."],n:"Faz subir da morada dos mortos: uma das primeiras expressões da esperança de Israel diante da morte."},
{v:7,l:["O Senhor empobrece e enriquece,","humilha e exalta;"]},
{v:8,l:["levanta do pó o fraco","e do monturo ergue o pobre,","para fazê-lo sentar-se com os príncipes","e ocupar um trono de glória.","Porque ao Senhor pertencem as colunas da terra, e sobre elas assentou o mundo."]},
{v:9,l:["Ele guarda os passos dos seus fiéis,","mas os ímpios calam-se nas trevas;","porque não é pela força que o homem triunfa."]},
{v:10,l:["O Senhor quebra os seus adversários;","do céu troveja contra eles.","O Senhor julga os confins da terra,","dá força ao seu rei","e exalta o poder do seu ungido."],n:"Ungido, em hebraico mashiah, Messias; em grego, Christos. É a primeira vez que a Bíblia usa a palavra para o rei — e Israel ainda não tem rei. O cântico olha para Davi e, para além dele, para o Messias."},
{s:"Os filhos de Heli"},
{v:11,t:"Elcana voltou para Ramá, para sua casa; e o menino ficou a serviço do Senhor, diante do sacerdote Heli.",np:1},
{v:12,t:"Os filhos de Heli eram homens perversos; não conheciam o Senhor",n:"Perversos, à letra filhos de Belial, como os homens de Gabaá no livro dos Juízes."},
{v:13,t:"nem o dever dos sacerdotes para com o povo. Quando alguém oferecia um sacrifício, o servo do sacerdote vinha, enquanto a carne cozia, com um garfo de três dentes na mão,"},
{v:14,t:"e o metia no caldeirão, na panela, no tacho ou na marmita; e tudo o que o garfo tirava, o sacerdote tomava para si. Assim faziam com todos os israelitas que iam a Silo.",n:"A Lei fixava a parte do sacerdote nos sacrifícios; os filhos de Heli tomam o que querem."},
{v:15,t:"Além disso, antes que se queimasse a gordura, o servo do sacerdote vinha e dizia ao que oferecia o sacrifício: Dá carne para assar para o sacerdote; ele não aceitará de ti carne cozida, só crua.",n:"A gordura pertencia a Deus e devia ser queimada primeiro. Os filhos de Heli passam à frente de Deus."},
{v:16,t:"E, se o homem lhe dizia: Primeiro queime-se a gordura, como é costume, e depois toma o que quiseres, ele respondia: Não; dá agora, senão tomarei à força."},
{v:17,t:"O pecado daqueles jovens era muito grande diante do Senhor, porque desprezavam a oferta do Senhor."},
{v:18,t:"Samuel servia diante do Senhor; era um menino, vestido com um efod de linho.",np:1,n:"O efod de linho era uma veste sacerdotal simples. O menino que serve contrasta com os sacerdotes que se servem."},
{v:19,t:"Sua mãe fazia-lhe uma pequena túnica e levava-a todos os anos, quando subia com o marido para oferecer o sacrifício anual."},
{v:20,t:"Heli abençoava Elcana e a sua mulher, dizendo: O Senhor te dê descendência desta mulher, em troca daquele que foi cedido ao Senhor. E eles voltavam para casa."},
{v:21,t:"O Senhor visitou Ana, e ela concebeu e deu à luz três filhos e duas filhas. E o menino Samuel crescia junto do Senhor."},
{v:22,t:"Heli era muito velho e ouviu tudo o que os seus filhos faziam a todo o Israel, e como se deitavam com as mulheres que serviam à entrada da tenda do encontro.",np:1},
{v:23,t:"E disse-lhes: Por que fazeis tais coisas? Ouço todo o povo falar das vossas más ações."},
{v:24,t:"Não, meus filhos; não é boa a fama que ouço: levais o povo do Senhor a pecar."},
{v:25,l:["Se um homem peca contra outro homem,","Deus pode ser o árbitro;","mas, se um homem peca contra o Senhor,","quem intercederá por ele?","Mas eles não escutaram a voz de seu pai, porque o Senhor queria fazê-los morrer."],n:"Nota do tradutor: o Senhor queria fazê-los morrer é o modo hebraico de dizer que a obstinação deles já os condenava; a Bíblia atribui a Deus o desfecho que o pecado prepara. Não quer dizer que Deus os impedisse de se converter."},
{v:26,t:"Mas o menino Samuel ia crescendo e agradava tanto ao Senhor como aos homens.",n:"São Lucas dirá o mesmo de Jesus menino: crescia em sabedoria, em estatura e em graça diante de Deus e dos homens."},
{s:"O anúncio contra a casa de Heli"},
{v:27,t:"Um homem de Deus veio ter com Heli e disse-lhe: Assim diz o Senhor: Não me revelei eu claramente à casa de teu pai, quando estavam no Egito, na casa do faraó?",np:1},
{v:28,t:"Escolhi-o dentre todas as tribos de Israel para ser meu sacerdote, para subir ao meu altar, queimar incenso e levar o efod diante de mim; e dei à casa de teu pai todas as ofertas queimadas dos filhos de Israel."},
{v:29,t:"Por que calcais aos pés os meus sacrifícios e as minhas ofertas, que ordenei para a minha morada? Por que honras os teus filhos mais do que a mim, engordando-vos com o melhor de todas as ofertas de Israel, meu povo?"},
{v:30,t:"Por isso diz o Senhor, Deus de Israel: Eu tinha dito que a tua casa e a casa de teu pai andariam diante de mim para sempre; mas agora, diz o Senhor, longe de mim tal coisa! Pois eu honro os que me honram, e os que me desprezam serão desprezados."},
{v:31,t:"Eis que virão dias em que cortarei o teu braço e o braço da casa de teu pai, de modo que não haverá velho na tua casa."},
{v:32,t:"Verás um rival na minha morada, em todo o bem que eu fizer a Israel; e não haverá mais velho na tua casa, em todos os dias."},
{v:33,t:"Não cortarei inteiramente do meu altar os teus descendentes, para que se consumam os teus olhos e se aflija a tua alma; mas a maior parte da tua casa morrerá na idade adulta.",n:"O anúncio cumpre-se em etapas: a morte de Ofni e Fineias, o massacre dos sacerdotes de Nob por Saul, e o afastamento de Abiatar por Salomão."},
{v:34,t:"Será para ti um sinal o que acontecerá a teus dois filhos, Ofni e Fineias: morrerão ambos no mesmo dia."},
{v:35,t:"Suscitarei para mim um sacerdote fiel, que agirá segundo o meu coração e a minha alma; edificarei para ele uma casa duradoura, e ele andará sempre diante do meu ungido.",n:"O sacerdote fiel será Sadoc, no tempo de Salomão. A Igreja viu, para além dele, Cristo, o sumo sacerdote fiel de que fala a Carta aos Hebreus."},
{v:36,t:"E todo aquele que restar da tua casa virá prostrar-se diante dele por uma moeda de prata e um pedaço de pão, e dirá: Admite-me, por favor, a alguma função sacerdotal, para que eu tenha um bocado de pão para comer."}
];

window.TEXTOS_SEED["1samuel"][3] = [
{s:"O chamado de Samuel"},
{v:1,t:"O menino Samuel servia o Senhor diante de Heli. Naqueles dias, a palavra do Senhor era rara, e as visões não eram frequentes.",n:"Rara, à letra preciosa, como o que escasseia. O livro começa num tempo de silêncio de Deus."},
{v:2,t:"Certo dia, Heli estava deitado no seu lugar; os seus olhos tinham começado a enfraquecer, e já não podia ver."},
{v:3,t:"A lâmpada de Deus ainda não se tinha apagado, e Samuel dormia no templo do Senhor, onde estava a arca de Deus.",n:"A lâmpada do santuário ardia de noite até a madrugada. Ainda não se apagara: é pouco antes do amanhecer — e também, na história de Israel, a luz de Deus ainda não se extinguiu."},
{v:4,t:"O Senhor chamou Samuel, e ele respondeu: Eis-me aqui!"},
{v:5,t:"Correu a Heli e disse: Eis-me aqui, porque me chamaste. Heli respondeu: Não te chamei; volta a deitar-te. E ele foi deitar-se."},
{v:6,t:"O Senhor chamou de novo: Samuel! Samuel levantou-se, foi a Heli e disse: Eis-me aqui, porque me chamaste. Heli respondeu: Não te chamei, meu filho; volta a deitar-te."},
{v:7,t:"Samuel ainda não conhecia o Senhor, e a palavra do Senhor ainda não lhe tinha sido revelada."},
{v:8,t:"O Senhor chamou Samuel pela terceira vez; ele levantou-se e foi a Heli"},
{v:9,t:"e disse: Eis-me aqui, porque me chamaste. Então Heli compreendeu que era o Senhor que chamava o menino, e disse a Samuel: Vai deitar-te; e, se te chamarem de novo, dirás: Fala, Senhor, porque o teu servo escuta. Samuel foi e deitou-se no seu lugar.",n:"O velho sacerdote, que não soube guiar os filhos, sabe ainda ensinar o menino a escutar. É a oração de todo chamado."},
{v:10,t:"O Senhor veio, pôs-se ali e chamou como das outras vezes: Samuel, Samuel! Samuel respondeu: Fala, porque o teu servo escuta.",np:1},
{v:11,t:"O Senhor disse a Samuel: Eis que vou fazer em Israel uma coisa que fará zunir os dois ouvidos de quem a ouvir."},
{v:12,t:"Naquele dia cumprirei contra Heli tudo o que disse a respeito da sua casa, do princípio ao fim."},
{v:13,t:"Anunciei-lhe que vou julgar a sua casa para sempre, por causa do pecado que ele conhecia: os seus filhos desprezavam a Deus, e ele não os repreendeu.",n:"O hebraico diz, por correção dos escribas, que os filhos se amaldiçoavam a si mesmos; a leitura antiga, conservada pela versão grega e pela Nova Vulgata, diz que desprezavam a Deus."},
{v:14,t:"Por isso jurei à casa de Heli que o pecado da casa de Heli jamais será expiado, nem por sacrifícios nem por ofertas."},
{v:15,t:"Samuel ficou deitado até de manhã; depois abriu as portas da casa do Senhor. Mas tinha medo de contar a visão a Heli.",np:1},
{v:16,t:"Heli chamou Samuel e disse: Samuel, meu filho! Ele respondeu: Eis-me aqui."},
{v:17,t:"Heli perguntou: Que foi que ele te disse? Não me escondas nada. Que Deus te faça isto e mais aquilo, se me esconderes uma só palavra de tudo o que ele te disse."},
{v:18,t:"Samuel contou-lhe tudo, sem nada esconder. E Heli disse: Ele é o Senhor; faça o que lhe parecer bom.",n:"A resignação de Heli tem grandeza: aceita o juízo de Deus sobre a sua casa."},
{v:19,t:"Samuel crescia, e o Senhor estava com ele e não deixava cair por terra nenhuma das suas palavras.",np:1,n:"Não deixava cair por terra: todas se cumpriam. É o sinal do verdadeiro profeta, segundo o Deuteronômio."},
{v:20,t:"Todo o Israel, desde Dã até Bersabeia, reconheceu que Samuel era um profeta acreditado do Senhor."},
{v:21,t:"O Senhor continuou a manifestar-se em Silo, porque o Senhor se revelava a Samuel em Silo, pela sua palavra. E a palavra de Samuel chegava a todo o Israel."}
];

window.TEXTOS_SEED["1samuel"][4] = [
{s:"A arca tomada pelos filisteus"},
{v:1,t:"Naqueles dias, os filisteus reuniram-se para a guerra contra Israel, e Israel saiu ao encontro dos filisteus para o combate e acampou junto a Ebenézer; os filisteus acamparam em Afec.",n:"O começo da guerra vem da versão grega, que a Nova Vulgata segue; o hebraico é aqui mais breve. Ebenézer quer dizer pedra do socorro: o nome só lhe será dado no capítulo 7, e o narrador o antecipa."},
{v:2,t:"Os filisteus dispuseram-se em linha de batalha contra Israel. Travou-se o combate, e Israel foi derrotado pelos filisteus, que mataram no campo de batalha cerca de quatro mil homens."},
{v:3,t:"O povo voltou ao acampamento, e os anciãos de Israel disseram: Por que o Senhor nos deixou derrotar hoje diante dos filisteus? Vamos buscar em Silo a arca da aliança do Senhor, para que venha para o meio de nós e nos salve da mão dos nossos inimigos.",n:"Os anciãos tratam a arca como um amuleto que obrigaria Deus a combater. O capítulo mostra que Deus não se deixa manipular."},
{v:4,t:"O povo mandou buscar em Silo a arca da aliança do Senhor dos exércitos, que está sentado sobre os querubins; e os dois filhos de Heli, Ofni e Fineias, estavam ali com a arca da aliança de Deus.",n:"Sentado sobre os querubins: a arca era o escabelo do trono invisível de Deus, guardado por dois querubins de ouro."},
{v:5,t:"Quando a arca da aliança do Senhor chegou ao acampamento, todo o Israel soltou um grande grito de guerra, e a terra estremeceu."},
{v:6,t:"Os filisteus ouviram o barulho do grito e disseram: Que significa este grande grito no acampamento dos hebreus? E souberam que a arca do Senhor tinha chegado ao acampamento.",n:"Hebreus é o nome que os estrangeiros dão aos israelitas, com uma ponta de desprezo."},
{v:7,t:"Os filisteus tiveram medo, porque diziam: Deus veio ao acampamento! E gemiam, dizendo:"},
{v:8,t:"Ai de nós! Nunca, até agora, houve tal júbilo entre eles. Ai de nós! Quem nos livrará da mão destes deuses poderosos? São os deuses que feriram o Egito com toda espécie de pragas no deserto."},
{v:9,t:"Coragem, filisteus, e sede homens, para não serdes escravos dos hebreus, como eles foram vossos escravos! Sede homens e combatei!"},
{v:10,t:"Os filisteus combateram, e Israel foi derrotado; cada um fugiu para a sua tenda. A derrota foi muito grande: caíram de Israel trinta mil homens de infantaria.",np:1},
{v:11,t:"A arca de Deus foi tomada, e os dois filhos de Heli, Ofni e Fineias, morreram.",n:"Cumpre-se o sinal anunciado a Heli: os dois filhos morrem no mesmo dia."},
{s:"A morte de Heli"},
{v:12,t:"Um homem de Benjamim correu do campo de batalha e chegou a Silo naquele mesmo dia, com as vestes rasgadas e a cabeça coberta de terra.",np:1,n:"Uma tradição judaica diz que esse mensageiro era Saul."},
{v:13,t:"Quando chegou, Heli estava sentado na cadeira, junto à porta, olhando para o caminho, porque o seu coração tremia pela arca de Deus. O homem entrou na cidade para dar a notícia, e toda a cidade soltou gritos."},
{v:14,t:"Heli ouviu o barulho dos gritos e perguntou: Que barulho é este? O homem veio depressa e deu a notícia a Heli."},
{v:15,t:"Heli tinha noventa e oito anos; os seus olhos tinham escurecido, e já não podia ver."},
{v:16,t:"O homem disse a Heli: Sou eu que vim do campo de batalha; fugi hoje do campo de batalha. Heli perguntou: Que aconteceu, meu filho?"},
{v:17,t:"O mensageiro respondeu: Israel fugiu diante dos filisteus, e houve grande mortandade entre o povo; também os teus dois filhos, Ofni e Fineias, morreram, e a arca de Deus foi tomada."},
{v:18,t:"Quando ele mencionou a arca de Deus, Heli caiu da cadeira para trás, junto à porta, quebrou o pescoço e morreu, porque era velho e pesado. Tinha julgado Israel durante quarenta anos.",n:"Não é a morte dos filhos que o derruba, mas a notícia da arca: o velho sacerdote amava a Deus mais do que soubera mostrar."},
{v:19,t:"Sua nora, mulher de Fineias, estava grávida e prestes a dar à luz. Quando ouviu a notícia de que a arca de Deus tinha sido tomada e de que o sogro e o marido tinham morrido, curvou-se e deu à luz, porque lhe sobrevieram as dores.",np:1},
{v:20,t:"No momento em que ia morrer, as mulheres que a assistiam disseram-lhe: Não tenhas medo, porque deste à luz um filho. Mas ela não respondeu nem fez caso."},
{v:21,t:"Deu ao menino o nome de Icabod, por causa da arca de Deus, que tinha sido tomada, e por causa do sogro e do marido; e disse: A glória foi exilada de Israel!",n:"Icabod quer dizer onde está a glória?, ou sem glória. A glória de Deus, a sua presença, parte para o exílio com a arca."},
{v:22,t:"E disse: A glória foi exilada de Israel, porque a arca de Deus foi tomada."}
];

window.TEXTOS_SEED["1samuel"][5] = [
{s:"A arca entre os filisteus"},
{v:1,t:"Os filisteus tomaram a arca de Deus e levaram-na de Ebenézer para Azoto."},
{v:2,t:"Tomaram a arca de Deus, levaram-na ao templo de Dagon e colocaram-na ao lado de Dagon.",n:"Pôr a arca junto do deus vencedor era o costume com os deuses dos vencidos: um troféu. O capítulo narra, com humor, a humilhação do deus vencedor."},
{v:3,t:"No dia seguinte, os habitantes de Azoto levantaram-se de madrugada, e eis que Dagon estava caído com o rosto por terra diante da arca do Senhor. Tomaram Dagon e o repuseram no seu lugar."},
{v:4,t:"No dia seguinte, levantaram-se de madrugada, e eis que Dagon estava de novo caído com o rosto por terra diante da arca do Senhor; e a cabeça de Dagon e as duas mãos estavam cortadas, sobre a soleira;"},
{v:5,t:"só o tronco de Dagon tinha ficado no seu lugar. Por isso, os sacerdotes de Dagon e todos os que entram no templo de Dagon não pisam a soleira de Dagon, em Azoto, até o dia de hoje.",n:"Dagon prostrado diante da arca: o deus dos vencedores adora o Deus dos vencidos. O costume de saltar a soleira, conhecido também em outros povos, é explicado pela história."},
{v:6,t:"A mão do Senhor pesou sobre os habitantes de Azoto; devastou-os e feriu-os de tumores, em Azoto e no seu território.",np:1,n:"Tumores: provavelmente a peste bubônica, transmitida pelos ratos, que o capítulo seguinte mencionará."},
{v:7,t:"Vendo o que acontecia, os homens de Azoto disseram: Que a arca do Deus de Israel não fique entre nós, porque a sua mão é dura contra nós e contra Dagon, o nosso deus."},
{v:8,t:"Mandaram reunir junto de si todos os príncipes dos filisteus e disseram: Que faremos com a arca do Deus de Israel? Eles responderam: Que a arca do Deus de Israel seja levada a Gat. E levaram para lá a arca do Deus de Israel."},
{v:9,t:"Depois que a levaram, a mão do Senhor pesou sobre a cidade, com um pânico muito grande; e feriu os homens da cidade, do menor ao maior, e brotaram-lhes tumores."},
{v:10,t:"Então mandaram a arca de Deus para Acaron. Mas, quando a arca de Deus chegou a Acaron, os acaronitas gritaram: Trouxeram-nos a arca do Deus de Israel, para nos matar, a nós e ao nosso povo!"},
{v:11,t:"Mandaram reunir todos os príncipes dos filisteus e disseram: Mandai embora a arca do Deus de Israel; volte ela para o seu lugar, e não nos mate, a nós e ao nosso povo."},
{v:12,t:"Pois havia um pânico mortal em toda a cidade, e a mão de Deus pesava muito sobre ela. Os que não morriam eram feridos de tumores, e o clamor da cidade subia até o céu."}
];

window.TEXTOS_SEED["1samuel"][6] = [
{s:"A arca devolvida a Israel"},
{v:1,t:"A arca do Senhor ficou sete meses na terra dos filisteus."},
{v:2,t:"Os filisteus chamaram os sacerdotes e os adivinhos e disseram: Que faremos com a arca do Senhor? Dizei-nos como a devolveremos ao seu lugar. Eles responderam:"},
{v:3,t:"Se devolverdes a arca do Deus de Israel, não a mandeis vazia, mas pagai-lhe uma oferta de reparação; então sereis curados e sabereis por que a sua mão não se afastava de vós."},
{v:4,t:"Eles perguntaram: Que oferta de reparação lhe devemos pagar? Responderam:"},
{v:5,t:"Segundo o número dos príncipes dos filisteus, cinco tumores de ouro e cinco ratos de ouro, porque a mesma praga atingiu todos vós e os vossos príncipes. Fareis imagens dos vossos tumores e imagens dos ratos que devastam a terra, e dareis glória ao Deus de Israel; talvez ele alivie a sua mão de sobre vós, de sobre os vossos deuses e de sobre a vossa terra.",n:"As imagens de ouro dos males eram oferendas conhecidas na antiguidade: devolvia-se à divindade a imagem da doença de que se pedia a cura."},
{v:6,t:"Por que endureceríeis o vosso coração, como os egípcios e o faraó endureceram o seu? Não foi depois de castigados por ele que os egípcios deixaram partir os israelitas, e eles se foram?",n:"Os filisteus conhecem a história do Êxodo: a fama do Deus de Israel corre entre os pagãos."},
{v:7,t:"Agora, pois, preparai um carro novo e tomai duas vacas que estejam amamentando, e que nunca tenham levado jugo; atrelai as vacas ao carro e prendei em casa os seus bezerros.",np:1},
{v:8,t:"Tomai a arca do Senhor e ponde-a no carro; e os objetos de ouro que lhe pagais como oferta de reparação, ponde-os numa caixa ao lado dela; e deixai-a ir."},
{v:9,t:"E observai: se ela subir pelo caminho do seu território, em direção a Bet-Sames, foi ele quem nos fez este grande mal; se não, saberemos que não foi a sua mão que nos feriu, mas foi um acaso que nos aconteceu.",n:"Vacas que amamentam, com os bezerros presos em casa, voltariam naturalmente para eles. Se forem na direção oposta, contra o instinto, é Deus quem as leva."},
{v:10,t:"Assim fizeram: tomaram duas vacas que amamentavam, atrelaram-nas ao carro e prenderam os bezerros em casa."},
{v:11,t:"Puseram no carro a arca do Senhor e a caixa com os ratos de ouro e as imagens dos tumores."},
{v:12,t:"As vacas foram direto pelo caminho de Bet-Sames; seguiam por uma única estrada, mugindo enquanto andavam, sem se desviarem nem para a direita nem para a esquerda. Os príncipes dos filisteus foram atrás delas até a fronteira de Bet-Sames.",n:"Mugindo: chamam os bezerros, e seguem no sentido contrário. É a imagem do sinal pedido."},
{v:13,t:"Os habitantes de Bet-Sames ceifavam o trigo no vale; levantaram os olhos, viram a arca e alegraram-se ao vê-la.",np:1},
{v:14,t:"O carro chegou ao campo de Josué, o betsamita, e parou ali. Havia ali uma grande pedra; racharam a madeira do carro e ofereceram as vacas em holocausto ao Senhor."},
{v:15,t:"Os levitas desceram a arca do Senhor e a caixa que estava junto dela, com os objetos de ouro, e puseram-nas sobre a grande pedra. Naquele dia, os homens de Bet-Sames ofereceram holocaustos e sacrifícios ao Senhor."},
{v:16,t:"Os cinco príncipes dos filisteus viram isso e voltaram a Acaron naquele mesmo dia."},
{v:17,t:"Estes são os tumores de ouro que os filisteus pagaram ao Senhor como oferta de reparação: um por Azoto, um por Gaza, um por Ascalon, um por Gat e um por Acaron;",np:1},
{v:18,t:"e os ratos de ouro eram tantos quantas as cidades dos filisteus pertencentes aos cinco príncipes, desde as cidades fortificadas até as aldeias sem muralha. E a grande pedra, sobre a qual puseram a arca do Senhor, está ainda hoje como testemunha no campo de Josué, o betsamita."},
{v:19,t:"Mas os filhos de Jeconias não se alegraram com os homens de Bet-Sames, quando viram a arca do Senhor; e o Senhor feriu setenta homens do povo. O povo ficou de luto, porque o Senhor ferira o povo com uma grande mortandade.",np:1,n:"Nota do tradutor: o hebraico diz que o Senhor feriu os homens de Bet-Sames por terem olhado para a arca do Senhor, e feriu do povo setenta homens, cinquenta mil homens — número duplo, que parece somar duas tradições. A Nova Vulgata segue aqui a versão grega, na qual a culpa é de um clã, os filhos de Jeconias, que ficaram indiferentes à volta da arca; e conserva só os setenta. Em um caso ou em outro, a lição é a mesma: a santidade de Deus não é coisa com que se brinque."},
{v:20,t:"E os homens de Bet-Sames disseram: Quem pode subsistir diante do Senhor, este Deus santo? E para quem subirá ele, saindo de nós?"},
{v:21,t:"Enviaram mensageiros aos habitantes de Cariat-Iarim, dizendo: Os filisteus devolveram a arca do Senhor; descei e levai-a para junto de vós."}
];

window.TEXTOS_SEED["1samuel"][7] = [
{s:"Samuel, juiz de Israel"},
{v:1,t:"Os homens de Cariat-Iarim vieram e levaram a arca do Senhor; introduziram-na na casa de Abinadab, na colina, e consagraram Eleazar, seu filho, para guardar a arca do Senhor.",n:"A arca ficará em Cariat-Iarim até que Davi a leve para Jerusalém. Silo, segundo Jeremias, foi destruída: por isso a arca não volta para lá."},
{v:2,t:"Desde o dia em que a arca ficou em Cariat-Iarim, passou muito tempo — vinte anos —, e toda a casa de Israel suspirava pelo Senhor.",np:1},
{v:3,t:"Samuel disse a toda a casa de Israel: Se é de todo o coração que voltais ao Senhor, tirai do meio de vós os deuses estrangeiros e as Astartes, dirigi o vosso coração para o Senhor e servi somente a ele; e ele vos livrará da mão dos filisteus."},
{v:4,t:"Os filhos de Israel tiraram do meio deles os baais e as Astartes e serviram somente ao Senhor."},
{v:5,t:"Samuel disse: Reuni todo o Israel em Masfa, e eu orarei ao Senhor por vós.",np:1},
{v:6,t:"Reuniram-se em Masfa, tiraram água e derramaram-na diante do Senhor; jejuaram naquele dia e disseram ali: Pecamos contra o Senhor. E Samuel julgou os filhos de Israel em Masfa.",n:"Derramar água diante do Senhor: rito de penitência de que não há outro exemplo na Bíblia. Talvez significasse o coração derramado como água, na expressão das Lamentações."},
{v:7,t:"Quando os filisteus souberam que os filhos de Israel se tinham reunido em Masfa, os príncipes dos filisteus subiram contra Israel. Os filhos de Israel souberam disso e tiveram medo dos filisteus,",np:1},
{v:8,t:"e disseram a Samuel: Não deixes de clamar por nós ao Senhor nosso Deus, para que nos salve da mão dos filisteus."},
{v:9,t:"Samuel tomou um cordeiro de leite e ofereceu-o inteiro em holocausto ao Senhor; e Samuel clamou ao Senhor por Israel, e o Senhor o atendeu."},
{v:10,t:"Enquanto Samuel oferecia o holocausto, os filisteus avançaram para combater contra Israel; mas o Senhor trovejou naquele dia com grande estrondo sobre os filisteus, lançou-os em pânico, e foram derrotados diante de Israel.",n:"Samuel vence como Moisés, pela oração: o povo não combate, e o céu troveja."},
{v:11,t:"Os homens de Israel saíram de Masfa, perseguiram os filisteus e derrotaram-nos até abaixo de Bet-Car."},
{v:12,t:"Samuel tomou uma pedra e colocou-a entre Masfa e Sen, e deu àquele lugar o nome de Ebenézer, isto é, Pedra do Socorro, dizendo: Até aqui o Senhor nos socorreu.",np:1,n:"O nome de Ebenézer, que no capítulo 4 marcava a derrota, marca agora a vitória. A frase de Samuel, até aqui o Senhor nos socorreu, tornou-se oração de agradecimento na tradição cristã."},
{v:13,t:"Os filisteus foram humilhados e não voltaram mais a entrar no território de Israel; e a mão do Senhor pesou sobre os filisteus durante todos os dias de Samuel."},
{v:14,t:"As cidades que os filisteus tinham tomado de Israel voltaram a Israel, desde Acaron até Gat; e Israel libertou o seu território da mão dos filisteus. E havia paz entre Israel e os amorreus."},
{v:15,t:"Samuel julgou Israel durante todos os dias da sua vida.",np:1},
{v:16,t:"Todos os anos, fazia um percurso por Betel, Guilgal e Masfa, e julgava Israel em todos esses lugares."},
{v:17,t:"Depois voltava a Ramá, porque ali estava a sua casa; e ali julgava Israel. E construiu ali um altar ao Senhor."}
];

window.TEXTOS_SEED["1samuel"][8] = [
{s:"O povo pede um rei"},
{v:1,t:"Quando Samuel envelheceu, constituiu seus filhos juízes de Israel."},
{v:2,t:"O primogênito chamava-se Joel, e o segundo, Abia; eram juízes em Bersabeia."},
{v:3,t:"Mas os filhos não andaram pelos caminhos do pai: desviaram-se atrás do lucro, aceitaram subornos e perverteram o direito.",n:"O drama de Heli repete-se com Samuel: os filhos do juiz justo não seguem o pai. É a ocasião do pedido de um rei."},
{v:4,t:"Então todos os anciãos de Israel se reuniram e foram ter com Samuel em Ramá,",np:1},
{v:5,t:"e disseram-lhe: Tu envelheceste, e os teus filhos não andam pelos teus caminhos. Agora, pois, constitui-nos um rei, para que nos julgue, como têm todas as nações.",n:"Como têm todas as nações: o povo escolhido quer ser como os outros. O Deuteronômio já previa este pedido e punha limites ao rei (Deuteronômio 17,14-20)."},
{v:6,t:"A palavra desagradou a Samuel, porque tinham dito: Dá-nos um rei, para que nos julgue. E Samuel orou ao Senhor."},
{v:7,t:"O Senhor disse a Samuel: Ouve a voz do povo em tudo o que te dizem; porque não é a ti que rejeitaram, é a mim que rejeitaram, para que eu não reine sobre eles.",n:"O verdadeiro rei de Israel é Deus, como dissera Gedeão: o Senhor reinará sobre vós. Deus consente no pedido, mas lhe dá o seu nome: uma rejeição."},
{v:8,t:"Conforme todas as obras que fizeram desde o dia em que os tirei do Egito até hoje, abandonando-me e servindo a outros deuses, assim fazem também contigo."},
{v:9,t:"Agora, pois, ouve a sua voz; mas adverte-os solenemente e dá-lhes a conhecer o direito do rei que reinará sobre eles."},
{v:10,t:"Samuel repetiu todas as palavras do Senhor ao povo que lhe pedia um rei,",np:1},
{v:11,t:"e disse: Este será o direito do rei que reinará sobre vós: tomará os vossos filhos e os destinará aos seus carros e à sua cavalaria, e eles correrão diante do seu carro;"},
{v:12,t:"fará deles chefes de mil e chefes de cinquenta, lavradores dos seus campos e ceifeiros das suas colheitas, fabricantes das suas armas de guerra e dos arreios dos seus carros."},
{v:13,t:"Tomará as vossas filhas para perfumistas, cozinheiras e padeiras."},
{v:14,t:"Tomará os vossos campos, as vossas vinhas e os vossos melhores olivais, e os dará aos seus servos."},
{v:15,t:"Cobrará o dízimo das vossas sementeiras e das vossas vinhas, para dá-lo aos seus eunucos e aos seus servos."},
{v:16,t:"Tomará os vossos servos e as vossas servas, os vossos melhores bois e os vossos jumentos, e os empregará nos seus trabalhos.",n:"Os melhores bois: assim a versão grega, que a Nova Vulgata segue; o hebraico diz os vossos melhores jovens."},
{v:17,t:"Cobrará o dízimo dos vossos rebanhos, e vós mesmos sereis seus escravos."},
{v:18,t:"Naquele dia clamareis por causa do rei que tiverdes escolhido, e o Senhor não vos responderá naquele dia.",n:"O retrato é o dos reis do Oriente, e será, com poucas exceções, o dos reis de Israel: Salomão e Roboão o cumprirão à letra."},
{v:19,t:"Mas o povo recusou-se a ouvir a voz de Samuel e disse: Não! Haverá um rei sobre nós,",np:1},
{v:20,t:"e seremos também nós como todas as nações: o nosso rei nos julgará, sairá à nossa frente e combaterá as nossas batalhas."},
{v:21,t:"Samuel ouviu todas as palavras do povo e repetiu-as aos ouvidos do Senhor."},
{v:22,t:"O Senhor disse a Samuel: Ouve a sua voz e constitui-lhes um rei. E Samuel disse aos homens de Israel: Volte cada um para a sua cidade."}
];

window.TEXTOS_SEED["1samuel"][9] = [
{s:"Saul procura as jumentas de seu pai"},
{v:1,t:"Havia um homem de Benjamim chamado Cis, filho de Abiel, filho de Seror, filho de Becorat, filho de Afia, benjaminita, homem poderoso."},
{v:2,t:"Tinha um filho chamado Saul, jovem e belo; não havia entre os filhos de Israel ninguém mais belo do que ele: dos ombros para cima, ultrapassava todo o povo.",n:"Saul quer dizer pedido: o nome lembra o pedido do povo. É o rei que o povo queria, alto e belo como os reis das nações."},
{v:3,t:"As jumentas de Cis, pai de Saul, extraviaram-se, e Cis disse a seu filho Saul: Leva contigo um dos servos, levanta-te e vai procurar as jumentas. Eles atravessaram a montanha de Efraim",np:1},
{v:4,t:"e a terra de Salisa, e não as encontraram; passaram pela terra de Salim, e não estavam lá; passaram pela terra de Benjamim, e não as acharam."},
{v:5,t:"Quando chegaram à terra de Suf, Saul disse ao servo que estava com ele: Vem, voltemos, para que meu pai não deixe de pensar nas jumentas e fique inquieto por nós."},
{v:6,t:"O servo respondeu-lhe: Há nesta cidade um homem de Deus, homem respeitado: tudo o que ele diz acontece sem falta. Vamos até lá; talvez nos oriente sobre a viagem que nos trouxe aqui."},
{v:7,t:"Saul disse ao seu servo: Pois bem, vamos; mas que levaremos ao homem? O pão acabou nos nossos alforjes, e não temos presente para dar ao homem de Deus. Que temos?",n:"Não se consultava um vidente de mãos vazias: o presente era o costume."},
{v:8,t:"O servo tornou a responder a Saul: Tenho aqui na mão um quarto de siclo de prata; nós o daremos ao homem de Deus, para que nos indique o caminho."},
{v:9,t:"Antigamente, em Israel, quem ia consultar a Deus dizia: Vinde, vamos ao vidente; porque o que hoje se chama profeta chamava-se antigamente vidente.",n:"Observação do narrador, que explica aos leitores do seu tempo uma palavra antiga, que vai aparecer logo adiante."},
{v:10,t:"Saul disse ao seu servo: Dizes bem; vem, vamos. E foram à cidade onde estava o homem de Deus."},
{v:11,t:"Subindo a ladeira da cidade, encontraram umas moças que saíam para tirar água e perguntaram-lhes: O vidente está aqui?",np:1},
{v:12,t:"Elas responderam: Está, sim; está aí à tua frente. Apressa-te agora, porque ele veio hoje à cidade, pois hoje há um sacrifício do povo no lugar alto.",n:"O lugar alto era o santuário ao ar livre, no alto de uma colina. Antes do templo de Jerusalém, o culto nesses lugares era legítimo."},
{v:13,t:"Logo que entrardes na cidade, o encontrareis, antes que ele suba ao lugar alto para comer; o povo não comerá antes que ele chegue, porque é ele quem abençoa o sacrifício, e depois comem os convidados. Subi, pois, agora, e logo o encontrareis."},
{v:14,t:"Subiram à cidade. Quando entravam na cidade, Samuel vinha saindo ao encontro deles, para subir ao lugar alto."},
{v:15,t:"Ora, um dia antes da chegada de Saul, o Senhor tinha feito a Samuel esta revelação:",np:1,n:"À letra, o Senhor tinha descoberto o ouvido de Samuel: tinha-lhe falado em segredo."},
{v:16,t:"Amanhã, a esta mesma hora, enviarei a ti um homem da terra de Benjamim; tu o ungirás como chefe do meu povo Israel, e ele salvará o meu povo da mão dos filisteus, porque olhei para o meu povo, pois o seu clamor chegou até mim.",n:"Chefe, em hebraico nagid: o designado, o príncipe escolhido por Deus. O texto ainda evita a palavra rei."},
{v:17,t:"Quando Samuel viu Saul, o Senhor lhe disse: Eis o homem de quem te falei; é ele quem governará o meu povo."},
{v:18,t:"Saul aproximou-se de Samuel no meio da porta e disse: Indica-me, por favor, onde é a casa do vidente."},
{v:19,t:"Samuel respondeu a Saul: O vidente sou eu. Sobe à minha frente ao lugar alto, e hoje comereis comigo. Amanhã cedo te deixarei partir, e te direi tudo o que tens no coração."},
{v:20,t:"Quanto às jumentas que perdeste há três dias, não te preocupes com elas, porque já foram encontradas. E para quem será tudo o que Israel tem de mais precioso? Não será para ti e para toda a casa de teu pai?",n:"Samuel responde à preocupação de Saul antes de ser perguntado, e já alude à realeza."},
{v:21,t:"Saul respondeu: Não sou eu um benjaminita, da menor das tribos de Israel? E a minha família não é a menor de todas as famílias da tribo de Benjamim? Por que, pois, me falas deste modo?",n:"Benjamim quase desaparecera na guerra contada no fim dos Juízes. A humildade de Saul lembra a de Gedeão."},
{v:22,t:"Samuel tomou Saul e o seu servo, levou-os à sala e deu-lhes lugar à cabeceira dos convidados, que eram cerca de trinta homens.",np:1},
{v:23,t:"Samuel disse ao cozinheiro: Traze a porção que te dei, aquela que te mandei guardar à parte."},
{v:24,t:"O cozinheiro tirou a coxa e a cauda e colocou-as diante de Saul. Samuel disse: Aqui está o que foi reservado; serve-te e come, porque foi guardado de propósito para ti, quando convidei o povo. E Saul comeu com Samuel naquele dia.",n:"A coxa era a porção de honra. A cauda: a Nova Vulgata segue uma correção provável do hebraico, que diz e o que estava sobre ela; a cauda gorda dos carneiros era parte escolhida."},
{v:25,t:"Desceram do lugar alto para a cidade. Prepararam uma cama para Saul no terraço, e ele dormiu.",np:1,n:"Assim a versão grega, que a Nova Vulgata segue; o hebraico diz que Samuel conversou com Saul no terraço. Os terraços planos das casas serviam de dormitório nas noites quentes."},
{v:26,t:"Levantaram-se cedo; ao romper do dia, Samuel chamou Saul no terraço, dizendo: Levanta-te, e eu te deixarei partir. Saul levantou-se, e saíram os dois, ele e Samuel."},
{v:27,t:"Quando desciam para a saída da cidade, Samuel disse a Saul: Dize ao servo que passe adiante de nós — e ele passou adiante —; tu, porém, para um momento, para que eu te faça ouvir a palavra do Senhor."}
];

window.TEXTOS_SEED["1samuel"][10] = [
{s:"Samuel unge Saul"},
{v:1,t:"Samuel tomou o frasco de óleo, derramou-o sobre a cabeça de Saul, beijou-o e disse: O Senhor te ungiu como chefe do seu povo Israel. Tu governarás o povo do Senhor e o livrarás da mão dos inimigos que o cercam. E este será para ti o sinal de que Deus te ungiu como chefe da sua herança:",n:"Grande parte do versículo, de tu governarás até da sua herança, falta no hebraico, por um salto do copista entre duas frases iguais; a Nova Vulgata a restitui a partir da versão grega. A unção fazia do rei o ungido do Senhor, em hebraico messias."},
{v:2,t:"quando hoje te afastares de mim, encontrarás dois homens junto ao sepulcro de Raquel, na fronteira de Benjamim, e eles te dirão: As jumentas que foste procurar foram encontradas; teu pai já não pensa nas jumentas, mas está inquieto por vós e diz: Que farei por meu filho?",n:"O hebraico acrescenta em Selsa, lugar desconhecido. Segundo esta tradição, o sepulcro de Raquel ficava no território de Benjamim, ao norte de Jerusalém; outra o põe junto de Belém."},
{v:3,t:"Partindo dali, irás mais adiante e chegarás ao carvalho do Tabor; ali te encontrarão três homens que sobem a Deus em Betel: um levando três cabritos, outro, três pães, e outro, um odre de vinho."},
{v:4,t:"Eles te saudarão e te darão dois pães, e tu os aceitarás das suas mãos."},
{v:5,t:"Depois disso, chegarás a Gabaá de Deus, onde há uma guarnição dos filisteus; e, ao entrares na cidade, encontrarás um grupo de profetas descendo do lugar alto, precedidos de harpa, tamborim, flauta e cítara, e eles estarão profetizando.",n:"Gabaá de Deus é talvez a própria Gabaá de Saul. Os grupos de profetas cantavam e dançavam ao som da música, num entusiasmo contagioso."},
{v:6,t:"O Espírito do Senhor se apoderará de ti, profetizarás com eles e serás mudado em outro homem."},
{v:7,t:"Quando esses sinais te acontecerem, faze o que a ocasião pedir, porque Deus está contigo."},
{v:8,t:"Depois descerás antes de mim a Guilgal; eu descerei para junto de ti, para oferecer holocaustos e sacrifícios de comunhão. Esperarás sete dias, até que eu chegue junto de ti e te mostre o que deves fazer.",n:"Esta ordem prepara a primeira falta de Saul, no capítulo 13."},
{s:"Saul entre os profetas"},
{v:9,t:"Assim que Saul voltou as costas para deixar Samuel, Deus lhe mudou o coração, e todos aqueles sinais se cumpriram naquele dia.",np:1},
{v:10,t:"Chegaram a Gabaá, e eis que um grupo de profetas veio ao seu encontro; o Espírito de Deus apoderou-se dele, e ele profetizou no meio deles."},
{v:11,t:"Todos os que o conheciam de antes, vendo-o profetizar com os profetas, diziam uns aos outros: Que aconteceu ao filho de Cis? Também Saul está entre os profetas?"},
{v:12,t:"Um homem do lugar respondeu: E quem é o pai deles? Por isso se tornou proverbial: Também Saul está entre os profetas?",n:"O pai era o mestre de um grupo de profetas. A resposta quer dizer: a profecia não se herda, é dom de Deus, que a dá a quem quer. O provérbio servia para falar de alguém que aparece onde não se esperava."},
{v:13,t:"Quando acabou de profetizar, foi a Gabaá.",n:"Assim a Nova Vulgata; o hebraico diz: foi ao lugar alto."},
{v:14,t:"O tio de Saul perguntou a ele e ao seu servo: Aonde fostes? Ele respondeu: Procurar as jumentas; e, como não as encontramos, fomos ter com Samuel.",np:1},
{v:15,t:"O tio disse: Conta-me, por favor, o que Samuel vos disse."},
{v:16,t:"Saul respondeu ao tio: Disse-nos que as jumentas tinham sido encontradas. Mas do assunto da realeza, de que Samuel lhe falara, não lhe contou nada."},
{s:"Saul escolhido rei por sorteio"},
{v:17,t:"Samuel convocou o povo diante do Senhor, em Masfa,",np:1},
{v:18,t:"e disse aos filhos de Israel: Assim diz o Senhor, Deus de Israel: Eu fiz Israel subir do Egito e vos livrei da mão dos egípcios e da mão de todos os reinos que vos oprimiam."},
{v:19,t:"Mas vós rejeitastes hoje o vosso Deus, que sozinho vos salvou de todos os vossos males e das vossas angústias, e dissestes: Não! Constitui um rei sobre nós! Agora, pois, apresentai-vos diante do Senhor por tribos e por clãs."},
{v:20,t:"Samuel fez aproximar todas as tribos de Israel, e a sorte caiu sobre a tribo de Benjamim.",np:1},
{v:21,t:"Fez aproximar a tribo de Benjamim por clãs, e a sorte caiu sobre o clã de Metri, e chegou até Saul, filho de Cis. Procuraram-no, mas ele não foi encontrado.",n:"O sorteio, como no caso de Acã no livro de Josué, deixa a escolha nas mãos de Deus."},
{v:22,t:"Consultaram de novo o Senhor, perguntando se o homem tinha vindo para ali; e o Senhor respondeu: Ei-lo escondido no meio das bagagens."},
{v:23,t:"Correram e tiraram-no dali; e, quando ele se pôs de pé no meio do povo, era mais alto do que todo o povo, dos ombros para cima."},
{v:24,t:"Samuel disse a todo o povo: Vedes aquele que o Senhor escolheu? Não há ninguém como ele em todo o povo. E todo o povo aclamou, gritando: Viva o rei!"},
{v:25,t:"Samuel expôs ao povo o direito da realeza, escreveu-o num livro e depositou-o diante do Senhor. Depois Samuel despediu todo o povo, cada um para a sua casa.",np:1,n:"O direito da realeza não é o direito do rei descrito em 8,11-18, mas o estatuto que limitava o poder do rei, à maneira do Deuteronômio. Depositado diante do Senhor, isto é, no santuário."},
{v:26,t:"Saul também voltou para sua casa, em Gabaá, e foram com ele os homens valentes cujo coração Deus tinha tocado."},
{v:27,t:"Mas alguns perversos disseram: Como poderá este nos salvar? E o desprezaram e não lhe trouxeram presentes. Ele, porém, fingiu não ouvir.",n:"Perversos: à letra filhos de Belial. Um manuscrito de Qumran traz aqui um parágrafo a mais, que conta como Naás, rei dos amonitas, oprimia as tribos da Transjordânia, arrancando-lhes o olho direito; a Nova Vulgata não o inclui."}
];

window.TEXTOS_SEED["1samuel"][11] = [
{s:"Saul liberta Jabes de Galaad"},
{v:1,t:"Naás, o amonita, subiu e começou a atacar Jabes de Galaad. Todos os homens de Jabes disseram a Naás: Faze aliança conosco, e nós te serviremos."},
{v:2,t:"Naás, o amonita, respondeu-lhes: Farei aliança convosco com esta condição: que eu arranque a todos vós o olho direito, e faça de vós a vergonha de todo o Israel.",n:"Sem o olho direito, o homem ficava inútil para a guerra, porque o escudo cobria o olho esquerdo, como explica Flávio Josefo; e a mutilação era uma humilhação para todo o povo."},
{v:3,t:"Os anciãos de Jabes disseram-lhe: Dá-nos sete dias, para enviarmos mensageiros por todo o território de Israel; e, se não houver quem nos defenda, sairemos e nos entregaremos a ti."},
{v:4,t:"Os mensageiros chegaram a Gabaá de Saul e referiram essas palavras aos ouvidos do povo; e todo o povo levantou a voz e chorou.",np:1,n:"Jabes de Galaad tinha laços de sangue com Benjamim: depois da guerra contada no fim dos Juízes, as moças de Jabes foram dadas como mulheres aos benjaminitas."},
{v:5,t:"Nisso Saul vinha do campo, atrás dos bois, e perguntou: Por que o povo está chorando? E contaram-lhe as palavras dos homens de Jabes.",n:"O rei ungido ainda lavra a terra: como os juízes, é chamado do meio da vida comum."},
{v:6,t:"Ao ouvir essas palavras, o Espírito do Senhor apoderou-se de Saul, e a sua ira se inflamou muito."},
{v:7,t:"Tomou uma junta de bois, cortou-os em pedaços e enviou-os por todo o território de Israel, por meio dos mensageiros, dizendo: Assim se fará com os bois de quem não sair atrás de Saul e de Samuel. O temor do Senhor caiu sobre o povo, e saíram como um só homem.",n:"O gesto lembra o do levita que esquartejou a concubina e enviou os pedaços às tribos, contra Benjamim (Juízes 19,29); agora é um benjaminita que convoca as tribos para salvar."},
{v:8,t:"Saul passou-os em revista em Bezec: os filhos de Israel eram trezentos mil, e os homens de Judá, trinta mil.",n:"A menção separada de Judá reflete a divisão posterior entre os reinos de Israel e de Judá."},
{v:9,t:"Saul disse aos mensageiros que tinham vindo: Assim direis aos homens de Jabes de Galaad: Amanhã, quando o sol aquecer, tereis a salvação. Os mensageiros foram e anunciaram isso aos homens de Jabes, que se alegraram,",np:1},
{v:10,t:"e disseram: Amanhã sairemos a vós, e fareis conosco tudo o que vos parecer bem.",n:"Dizem-no aos amonitas, com ironia: fingem render-se, para que o inimigo se descuide."},
{v:11,t:"No dia seguinte, Saul dividiu o povo em três grupos; eles penetraram no meio do acampamento na vigília da manhã e bateram os amonitas até o calor do dia. Os que sobreviveram dispersaram-se, de modo que não ficaram dois deles juntos.",np:1,n:"A vigília da manhã era a última parte da noite, antes da aurora."},
{s:"A realeza renovada em Guilgal"},
{v:12,t:"O povo disse a Samuel: Quem é que dizia: Acaso Saul reinará sobre nós? Entregai esses homens, e nós os mataremos.",np:1},
{v:13,t:"Mas Saul disse: Ninguém será morto neste dia, porque hoje o Senhor realizou a salvação em Israel.",n:"O primeiro ato de Saul depois da vitória é o perdão: a vitória é do Senhor, e não dele."},
{v:14,t:"Samuel disse ao povo: Vinde, vamos a Guilgal, e renovemos ali a realeza."},
{v:15,t:"Todo o povo foi a Guilgal, e ali proclamaram Saul rei diante do Senhor, em Guilgal; ofereceram ali sacrifícios de comunhão diante do Senhor, e Saul e todos os homens de Israel se alegraram muito."}
];

window.TEXTOS_SEED["1samuel"][12] = [
{s:"O discurso de despedida de Samuel"},
{v:1,t:"Samuel disse a todo o Israel: Ouvi a vossa voz em tudo o que me dissestes e constituí um rei sobre vós."},
{v:2,t:"Agora, eis o rei que caminha à vossa frente. Quanto a mim, estou velho e de cabelos brancos, e os meus filhos estão convosco. Andei diante de vós desde a minha juventude até hoje;"},
{v:3,t:"aqui estou. Testemunhai contra mim diante do Senhor e diante do seu ungido: de quem tomei o boi? De quem tomei o jumento? A quem defraudei? A quem oprimi? Da mão de quem aceitei presente para fechar os olhos em sua causa? Eu vos restituirei.",n:"Samuel presta contas, como fará Paulo em Mileto (Atos 20,33). O contraste com o direito do rei é deliberado: o rei tomará; Samuel nada tomou."},
{v:4,t:"Eles responderam: Não nos defraudaste, nem nos oprimiste, nem tomaste coisa alguma da mão de ninguém."},
{v:5,t:"Ele lhes disse: O Senhor é testemunha contra vós, e o seu ungido é testemunha neste dia, de que nada achastes na minha mão. Responderam: Ele é testemunha."},
{v:6,t:"Samuel disse ao povo: Testemunha é o Senhor, que suscitou Moisés e Aarão e fez os nossos pais subirem da terra do Egito.",np:1},
{v:7,t:"Agora, pois, ficai aqui, para que eu entre em juízo convosco diante do Senhor, lembrando todos os benefícios que o Senhor fez a vós e a vossos pais:"},
{v:8,t:"quando Jacó entrou no Egito, e os egípcios os oprimiram, vossos pais clamaram ao Senhor, e o Senhor enviou Moisés e Aarão, que tiraram vossos pais do Egito e os estabeleceram neste lugar."},
{v:9,t:"Mas eles se esqueceram do Senhor seu Deus, e ele os entregou nas mãos de Sísara, chefe do exército de Hasor, nas mãos dos filisteus e nas mãos do rei de Moab, que lhes fizeram guerra."},
{v:10,t:"Então clamaram ao Senhor e disseram: Pecamos, porque abandonamos o Senhor e servimos aos baais e às Astartes; agora, livra-nos da mão dos nossos inimigos, e te serviremos."},
{v:11,t:"E o Senhor enviou Jerobaal, Barac, Jefté e Samuel, e vos livrou da mão dos inimigos que vos cercavam, e habitastes em segurança.",n:"Barac: assim a versão grega, que a Nova Vulgata segue; o hebraico diz Badã, juiz desconhecido. Jerobaal é Gedeão. Samuel conta-se a si mesmo entre os libertadores."},
{v:12,t:"Mas, quando vistes que Naás, rei dos amonitas, vinha contra vós, dissestes-me: Não! Um rei reinará sobre nós! — quando o Senhor vosso Deus era o vosso rei."},
{v:13,t:"Agora, pois, aqui está o rei que escolhestes e pedistes: eis que o Senhor vos deu um rei."},
{v:14,t:"Se temerdes o Senhor, se o servirdes e ouvirdes a sua voz, e não desprezardes a palavra do Senhor, vós e o rei que reina sobre vós seguireis o Senhor vosso Deus."},
{v:15,t:"Mas, se não ouvirdes a voz do Senhor e desprezardes a palavra do Senhor, a mão do Senhor estará contra vós e contra o vosso rei, para vos destruir.",n:"Contra o vosso rei: assim a versão grega; o hebraico diz contra vossos pais."},
{s:"O trovão na colheita do trigo"},
{v:16,t:"Agora, pois, ficai aqui e vede esta grande coisa que o Senhor vai fazer diante dos vossos olhos.",np:1},
{v:17,t:"Não é hoje a colheita do trigo? Invocarei o Senhor, e ele enviará trovões e chuva; e reconhecereis e vereis quão grande é o mal que fizestes aos olhos do Senhor, pedindo para vós um rei.",n:"A colheita do trigo, em maio e junho, cai na estação seca, quando quase nunca chove em Israel. A chuva fora de tempo era sinal evidente, e ameaça para a colheita."},
{v:18,t:"Samuel invocou o Senhor, e o Senhor enviou trovões e chuva naquele dia."},
{v:19,t:"Todo o povo teve grande temor do Senhor e de Samuel, e todo o povo disse a Samuel: Ora ao Senhor teu Deus por teus servos, para que não morramos, porque a todos os nossos pecados acrescentamos este mal de pedirmos para nós um rei."},
{v:20,t:"Samuel disse ao povo: Não temais. Vós fizestes todo esse mal; contudo, não vos afasteis do Senhor, mas servi o Senhor de todo o vosso coração.",np:1},
{v:21,t:"Não vos desvieis atrás das coisas vãs, que não vos podem ajudar nem livrar, porque são vãs.",n:"Coisas vãs: os ídolos, que o hebraico chama tohu, o vazio."},
{v:22,t:"Por causa do seu grande nome, o Senhor não abandonará o seu povo, porque o Senhor se dignou fazer de vós o seu povo."},
{v:23,t:"Quanto a mim, longe de mim pecar contra o Senhor deixando de orar por vós; e vos ensinarei o caminho bom e reto.",n:"Samuel deixa de governar, mas não de interceder: deixar de orar pelo povo seria, para ele, um pecado."},
{v:24,t:"Somente temei o Senhor e servi-o com fidelidade, de todo o vosso coração; vede as grandes coisas que ele fez por vós."},
{v:25,t:"Mas, se persistirdes no mal, perecereis, vós e o vosso rei."}
];

window.TEXTOS_SEED["1samuel"][13] = [
{s:"Começa a guerra contra os filisteus"},
{v:1,t:"Saul tinha … anos quando começou a reinar, e reinou dois anos sobre Israel.",n:"Nota do tradutor: o texto hebraico está incompleto: diz à letra Saul tinha um ano, e o número caiu. A Nova Vulgata deixa a lacuna. Os dois anos de reinado também parecem truncados; Atos 13,21 dá a Saul quarenta anos de reinado."},
{v:2,t:"Saul escolheu para si três mil homens de Israel: dois mil estavam com Saul em Micmás e na montanha de Betel, e mil com Jônatas em Gabaá de Benjamim; o resto do povo, mandou-o embora, cada um para a sua tenda.",n:"Jônatas, filho de Saul, aparece aqui pela primeira vez, já como chefe."},
{v:3,t:"Jônatas atacou o posto dos filisteus que estava em Gabaá, e os filisteus souberam disso. Saul mandou tocar a trombeta por toda a terra, dizendo: Ouçam os hebreus!"},
{v:4,t:"Todo o Israel ouviu esta notícia: Saul atacou o posto dos filisteus, e Israel tornou-se odioso aos filisteus. E o povo foi convocado para junto de Saul, em Guilgal."},
{v:5,t:"Os filisteus reuniram-se para combater contra Israel: três mil carros, seis mil cavaleiros e uma multidão de soldados, numerosa como a areia da praia do mar. Subiram e acamparam em Micmás, a leste de Bet-Áven.",np:1,n:"Três mil carros: assim alguns manuscritos gregos e a Nova Vulgata; o hebraico diz trinta mil, número inverossímil."},
{v:6,t:"Os homens de Israel, vendo-se em apuros — porque o povo estava acuado —, esconderam-se nas cavernas, nos esconderijos, entre os rochedos, nas grutas e nas cisternas."},
{v:7,t:"Alguns hebreus passaram o Jordão, para a terra de Gad e de Galaad. Saul ainda estava em Guilgal, e todo o povo que o seguia tremia de medo.",n:"O narrador joga com o nome hebreus e o verbo passar, avar em hebraico: os hebreus passam o Jordão, fugindo."},
{s:"A desobediência de Saul"},
{v:8,t:"Esperou sete dias, conforme o prazo marcado por Samuel; mas Samuel não chegava a Guilgal, e o povo começava a abandonar Saul.",np:1},
{v:9,t:"Então Saul disse: Trazei-me o holocausto e os sacrifícios de comunhão. E ofereceu o holocausto."},
{v:10,t:"Mal tinha acabado de oferecer o holocausto, eis que Samuel chegou; e Saul saiu ao seu encontro para saudá-lo."},
{v:11,t:"Samuel perguntou: Que fizeste? Saul respondeu: Vi que o povo me abandonava, que tu não tinhas vindo no prazo marcado e que os filisteus estavam reunidos em Micmás;"},
{v:12,t:"e disse comigo: Agora os filisteus vão descer contra mim em Guilgal, e eu ainda não implorei o favor do Senhor. Forçado pela necessidade, ofereci o holocausto."},
{v:13,t:"Samuel disse a Saul: Procedeste como insensato. Oxalá tivesses guardado os mandamentos que o Senhor teu Deus te deu! Agora o Senhor teria firmado para sempre o teu reino sobre Israel;"},
{v:14,t:"mas o teu reino não subsistirá. O Senhor procurou para si um homem segundo o seu coração e o constituiu chefe do seu povo, porque não guardaste o que o Senhor te ordenou.",n:"Um homem segundo o seu coração: Davi, como dirá Paulo em Atos 13,22. A falta de Saul parece pequena; mas o rei de Israel devia obedecer à palavra do profeta, e Saul pôs a sua prudência acima dela."},
{v:15,t:"Samuel levantou-se e saiu de Guilgal, seguindo o seu caminho. O resto do povo subiu atrás de Saul, ao encontro dos homens de guerra, e foram de Guilgal a Gabaá de Benjamim. Saul passou em revista a gente que estava com ele: cerca de seiscentos homens.",n:"O trecho sobre o resto do povo vem da versão grega, que a Nova Vulgata segue; o hebraico diz apenas que Samuel subiu de Guilgal a Gabaá de Benjamim."},
{s:"Israel sem ferreiros"},
{v:16,t:"Saul, seu filho Jônatas e o povo que estava com eles ficaram em Gabaá de Benjamim, enquanto os filisteus acampavam em Micmás.",np:1},
{v:17,t:"Do acampamento dos filisteus saíram três grupos para saquear: um tomou o caminho de Efra, para a terra de Sual;"},
{v:18,t:"outro tomou o caminho de Bet-Horon; e o terceiro tomou o caminho da fronteira que domina o vale de Seboim, voltado para o deserto."},
{v:19,t:"Não se encontrava ferreiro em toda a terra de Israel, porque os filisteus tinham tomado precauções para que os hebreus não fizessem espadas nem lanças.",np:1,n:"Os filisteus dominavam a técnica do ferro e guardavam o monopólio: era a maneira de manter Israel desarmado."},
{v:20,t:"Todo o Israel tinha de descer aos filisteus para afiar cada um a sua relha, a sua enxada, o seu machado e a sua foice."},
{v:21,t:"O preço da afiação era de dois terços de siclo pelas relhas e pelas enxadas, e de um terço de siclo para afiar os machados e consertar os aguilhões.",n:"Dois terços de siclo: em hebraico pim, palavra que só se entendeu quando os arqueólogos encontraram pesos de pedra com esta inscrição. Preço alto: a dependência custava caro."},
{v:22,t:"No dia da batalha de Micmás, não se encontrava espada nem lança na mão de ninguém do povo que estava com Saul e Jônatas; só Saul e seu filho Jônatas as tinham."},
{v:23,t:"Um posto dos filisteus avançou até o desfiladeiro de Micmás."}
];

window.TEXTOS_SEED["1samuel"][14] = [
{s:"A façanha de Jônatas"},
{v:1,t:"Certo dia, Jônatas, filho de Saul, disse ao jovem que lhe carregava as armas: Vem, passemos ao posto dos filisteus que está do outro lado. Mas não disse nada a seu pai."},
{v:2,t:"Saul estava nos arredores de Gabaá, debaixo da romãzeira que há em Magron; e o povo que estava com ele era de cerca de seiscentos homens."},
{v:3,t:"Aías, filho de Aquitob, irmão de Icabod, filho de Fineias, filho de Heli, sacerdote do Senhor em Silo, trazia o efod. E o povo não sabia que Jônatas tinha saído.",n:"Aías é bisneto de Heli: a casa condenada ainda serve junto do rei, com o efod, pelo qual se consultava a Deus. O nome de Icabod lembra a glória perdida."},
{v:4,t:"Entre as passagens pelas quais Jônatas procurava chegar ao posto dos filisteus, havia um penhasco de um lado e um penhasco do outro: um chamava-se Bosés, e o outro, Sené;",np:1,n:"À letra, um dente de rocha: dois rochedos pontiagudos, dos dois lados do desfiladeiro."},
{v:5,t:"um rochedo erguia-se ao norte, defronte de Micmás, e o outro ao sul, defronte de Gabaá."},
{v:6,t:"Jônatas disse ao jovem que lhe carregava as armas: Vem, passemos ao posto destes incircuncisos; talvez o Senhor faça algo por nós, porque nada impede o Senhor de salvar, com muitos ou com poucos.",n:"É a fé de Gedeão: a vitória não depende do número."},
{v:7,t:"O escudeiro respondeu-lhe: Faze tudo o que tens no coração. Vai aonde quiseres; eu estarei contigo aonde fores."},
{v:8,t:"Jônatas disse: Vamos passar para junto desses homens. Quando nos mostrarmos a eles,"},
{v:9,t:"se nos disserem: Parai aí, até que cheguemos a vós, ficaremos no nosso lugar e não subiremos até eles."},
{v:10,t:"Mas, se disserem: Subi até nós, subiremos, porque o Senhor os entregou nas nossas mãos: este será o sinal para nós."},
{v:11,t:"Os dois se mostraram ao posto dos filisteus, e os filisteus disseram: Olhai, os hebreus estão saindo dos buracos onde se tinham escondido!"},
{v:12,t:"Os homens do posto gritaram a Jônatas e ao seu escudeiro: Subi até nós, e vos daremos uma lição! Jônatas disse ao seu escudeiro: Sobe atrás de mim, porque o Senhor os entregou nas mãos de Israel."},
{v:13,t:"Jônatas subiu trepando com as mãos e os pés, e o escudeiro atrás dele. Os filisteus caíam diante de Jônatas, e o escudeiro, que vinha atrás, os matava."},
{v:14,t:"Nesse primeiro golpe, Jônatas e o seu escudeiro mataram cerca de vinte homens, num espaço de mais ou menos meia jeira de terra.",n:"A jeira era a área que uma junta de bois lavrava num dia."},
{v:15,t:"Houve pânico no acampamento, no campo e em todo o povo; o posto e os que tinham saído para saquear ficaram também apavorados; a terra tremeu, e foi um pânico enviado por Deus."},
{v:16,t:"As sentinelas de Saul, em Gabaá de Benjamim, olharam, e eis que a multidão se dispersava, correndo para cá e para lá.",np:1},
{v:17,t:"Saul disse ao povo que estava com ele: Fazei a contagem e vede quem saiu do meio de nós. Fizeram a contagem, e viram que faltavam Jônatas e o seu escudeiro."},
{v:18,t:"Saul disse a Aías: Traze o efod. Pois naquele dia era ele quem levava o efod diante dos filhos de Israel.",n:"Assim a versão grega, que a Nova Vulgata segue; o hebraico diz: Traze a arca de Deus, porque a arca de Deus estava naquele dia com os filhos de Israel. A arca estava então em Cariat-Iarim, e era com o efod que se consultava a Deus."},
{v:19,t:"Enquanto Saul falava com o sacerdote, o tumulto no acampamento dos filisteus crescia cada vez mais. Então Saul disse ao sacerdote: Retira a mão.",n:"Retira a mão: Saul interrompe a consulta, impaciente; os fatos já parecem responder."},
{v:20,t:"Saul e todo o povo que estava com ele reuniram-se e foram até o lugar do combate; e eis que a espada de cada um se voltava contra o seu companheiro: era uma confusão enorme."},
{v:21,t:"Também os hebreus que antes estavam com os filisteus e tinham subido com eles ao acampamento passaram para o lado de Israel, que estava com Saul e Jônatas."},
{v:22,t:"Todos os israelitas que se tinham escondido na montanha de Efraim, ouvindo que os filisteus fugiam, também se juntaram aos seus no combate."},
{v:23,t:"Assim o Senhor salvou Israel naquele dia; e o combate estendeu-se para além de Bet-Áven."},
{s:"O juramento de Saul"},
{v:24,t:"Naquele dia os homens de Israel estavam extenuados. Saul tinha imposto ao povo este juramento: Maldito o homem que comer alguma coisa antes da tarde, antes que eu me vingue dos meus inimigos! E ninguém do povo provou alimento.",np:1,n:"O juramento é um zelo mal calculado: priva de forças os combatentes em plena perseguição. E as palavras dos meus inimigos mostram que Saul pensa na sua própria vingança."},
{v:25,t:"Todo o povo chegou a um bosque, e havia mel no chão."},
{v:26,t:"O povo entrou no bosque, e eis que o mel escorria; mas ninguém levou a mão à boca, porque o povo temia o juramento."},
{v:27,t:"Jônatas, porém, não tinha ouvido quando seu pai impusera o juramento ao povo; estendeu a ponta da vara que tinha na mão, molhou-a no favo de mel e levou a mão à boca, e os seus olhos se iluminaram.",n:"Os olhos se iluminaram: recobrou as forças. O olhar do homem exausto se apaga."},
{v:28,t:"Um do povo lhe disse: Teu pai impôs solenemente ao povo este juramento: Maldito o homem que comer alguma coisa hoje! E o povo está exausto."},
{v:29,t:"Jônatas respondeu: Meu pai trouxe desgraça à terra! Vede como os meus olhos se iluminaram, por ter provado um pouco deste mel.",n:"Trouxe desgraça: o mesmo verbo que Josué usa para Acã, o homem que desgraçou Israel (Josué 7,25)."},
{v:30,t:"Quanto mais, se o povo tivesse comido hoje dos despojos que encontrou dos seus inimigos! Não teria sido maior a derrota dos filisteus?"},
{v:31,t:"Naquele dia bateram os filisteus desde Micmás até Aialon; e o povo ficou extremamente cansado.",np:1},
{v:32,t:"Então o povo se lançou sobre os despojos: tomou ovelhas, bois e bezerros, degolou-os no chão e comeu a carne com o sangue.",n:"A Lei proibia comer a carne com o sangue (Levítico 17,10-14; Deuteronômio 12,23): o sangue é a vida, e a vida pertence a Deus. Degolados no chão, os animais não se esvaíam de todo."},
{v:33,t:"Foram dizer a Saul: O povo está pecando contra o Senhor, comendo carne com sangue. Ele disse: Fostes infiéis! Rolai para cá, para junto de mim, uma pedra grande."},
{v:34,t:"E Saul disse: Espalhai-vos entre o povo e dizei a cada um que traga até mim o seu boi e o seu carneiro; degolai-os aqui e comei, e não pecareis contra o Senhor comendo a carne com o sangue. E todos trouxeram naquela noite o que tinham à mão e os degolaram ali."},
{v:35,t:"Saul construiu um altar ao Senhor: foi o primeiro altar que construiu ao Senhor."},
{v:36,t:"Saul disse: Lancemo-nos esta noite sobre os filisteus e saqueemo-los até o amanhecer, sem deixar um só deles com vida. Responderam: Faze tudo o que te parecer bem. Mas o sacerdote disse: Aproximemo-nos aqui de Deus.",np:1},
{v:37,t:"Saul consultou a Deus: Devo perseguir os filisteus? Tu os entregarás nas mãos de Israel? Mas naquele dia Deus não lhe respondeu."},
{v:38,t:"Saul disse: Aproximai-vos daqui, todos os chefes do povo; procurai e vede por quem aconteceu hoje este pecado."},
{v:39,t:"Pela vida do Senhor, salvador de Israel: ainda que tenha sido por meu filho Jônatas, ele morrerá sem remissão. E ninguém de todo o povo lhe respondeu.",n:"O silêncio do povo é eloquente: todos sabiam o que Jônatas tinha feito."},
{v:40,t:"E disse a todo o Israel: Ficai vós de um lado, e eu e meu filho Jônatas ficaremos do outro. O povo respondeu a Saul: Faze o que te parecer bem."},
{v:41,t:"Saul disse ao Senhor, Deus de Israel: Por que não respondeste hoje ao teu servo? Se esta culpa está em mim ou em meu filho Jônatas, Senhor, Deus de Israel, dá Urim; mas, se esta culpa está no teu povo Israel, dá Tumim. E a sorte caiu sobre Jônatas e Saul, e o povo ficou livre.",n:"A oração de Saul vem da versão grega, que a Nova Vulgata segue; o hebraico, por um salto do copista, conserva apenas: dá um sinal certo, tamim. Urim e Tumim eram as sortes sagradas, guardadas no peitoral do sumo sacerdote: davam uma resposta de sim ou não."},
{v:42,t:"Saul disse: Lançai a sorte entre mim e meu filho Jônatas. E a sorte caiu sobre Jônatas."},
{v:43,t:"Saul disse a Jônatas: Conta-me o que fizeste. Jônatas contou-lhe: Provei um pouco de mel com a ponta da vara que tinha na mão. Aqui estou; morrerei."},
{v:44,t:"Saul disse: Que Deus me faça isto e mais aquilo, se tu não morreres, Jônatas!"},
{v:45,t:"Mas o povo disse a Saul: Há de morrer Jônatas, que realizou esta grande salvação em Israel? Nunca! Pela vida do Senhor, não cairá por terra um só cabelo da sua cabeça, porque foi com Deus que ele agiu hoje. Assim o povo resgatou Jônatas, e ele não morreu.",n:"Resgatou: a palavra sugere que o povo pagou pela vida de Jônatas, talvez com um sacrifício de substituição. O povo julga melhor que o rei: Jônatas não transgrediu o juramento conscientemente."},
{v:46,t:"Saul deixou de perseguir os filisteus, e os filisteus voltaram para a sua terra."},
{s:"Resumo do reinado de Saul"},
{v:47,t:"Quando Saul se firmou no reino de Israel, combateu contra todos os inimigos ao redor: contra Moab, contra os amonitas, contra Edom, contra os reis de Soba e contra os filisteus; e, para onde quer que se voltasse, saía vitorioso.",np:1,n:"Saía vitorioso: assim a versão grega; o hebraico diz, talvez por erro, agia como culpado."},
{v:48,t:"Agiu com valentia, derrotou Amalec e livrou Israel da mão dos que o saqueavam."},
{v:49,t:"Os filhos de Saul foram Jônatas, Isvi e Melquisua; as suas duas filhas chamavam-se: a mais velha, Merob, e a mais nova, Micol.",np:1,n:"Isvi é talvez o mesmo Isbaal que reinará depois de Saul; o capítulo 31 menciona ainda outro filho, Abinadab."},
{v:50,t:"A mulher de Saul chamava-se Aquinoam, filha de Aquimaás; e o chefe do seu exército chamava-se Abner, filho de Ner, tio de Saul."},
{v:51,t:"Cis, pai de Saul, e Ner, pai de Abner, eram filhos de Abiel."},
{v:52,t:"Durante toda a vida de Saul, houve guerra encarniçada contra os filisteus; e sempre que Saul via um homem valente e apto para a guerra, tomava-o a seu serviço.",np:1}
];

window.TEXTOS_SEED["1samuel"][15] = [
{s:"A guerra contra Amalec"},
{v:1,t:"Samuel disse a Saul: Foi a mim que o Senhor enviou para te ungir rei sobre o seu povo Israel. Agora, pois, ouve a voz do Senhor."},
{v:2,t:"Assim diz o Senhor dos exércitos: Tenho presente tudo o que Amalec fez a Israel, como se lhe opôs no caminho, quando subia do Egito.",n:"Amalec atacou Israel no deserto, logo depois da saída do Egito, atingindo os mais fracos da retaguarda (Êxodo 17,8-16; Deuteronômio 25,17-19)."},
{v:3,t:"Agora, pois, vai, fere Amalec e vota ao extermínio tudo o que lhe pertence; não o poupes, mas mata homens e mulheres, crianças e bebês de peito, bois e ovelhas, camelos e jumentos.",n:"Votar ao extermínio: a lei da guerra santa, o herem, como na conquista de Jericó. Nada do que é votado pode ser tomado como despojo: tudo pertence a Deus. É a lógica de um tempo que o Evangelho superou; mas a narrativa julga Saul pela sua desobediência, não pela sua compaixão."},
{v:4,t:"Saul convocou o povo e passou-o em revista em Telém: duzentos mil homens de infantaria e dez mil homens de Judá.",np:1},
{v:5,t:"Saul chegou até a cidade de Amalec e armou uma emboscada no vale."},
{v:6,t:"E Saul disse aos quenitas: Ide, retirai-vos, saí do meio dos amalecitas, para que eu não vos destrua com eles; porque fostes bondosos para com todos os filhos de Israel, quando subiam do Egito. E os quenitas retiraram-se do meio dos amalecitas.",n:"Os quenitas eram aparentados com Moisés, cujo sogro era quenita, e acompanharam Israel desde o deserto (Juízes 1,16)."},
{v:7,t:"Saul feriu os amalecitas desde Hévila até Sur, que fica defronte do Egito."},
{v:8,t:"Apanhou vivo Agag, rei de Amalec, e passou ao fio da espada todo o povo."},
{v:9,t:"Mas Saul e o povo pouparam Agag e o melhor das ovelhas e dos bois, os animais gordos e os cordeiros, e tudo o que era bom; não quiseram votá-los ao extermínio. Só o que era sem valor e desprezível votaram ao extermínio."},
{s:"Saul rejeitado"},
{v:10,t:"A palavra do Senhor foi dirigida a Samuel nestes termos:",np:1},
{v:11,t:"Arrependo-me de ter constituído Saul rei, porque ele se afastou de mim e não cumpriu as minhas palavras. Samuel entristeceu-se e clamou ao Senhor a noite inteira."},
{v:12,t:"Samuel levantou-se cedo para ir ao encontro de Saul pela manhã; e informaram a Samuel: Saul foi a Carmel, erigiu ali um monumento para si; depois deu a volta e desceu a Guilgal.",n:"Carmel é uma cidade de Judá, ao sul de Hebron, e não o monte Carmelo. O monumento à sua própria glória já mostra a mudança de Saul, que se julgava pequeno aos próprios olhos."},
{v:13,t:"Quando Samuel chegou junto de Saul, Saul lhe disse: Bendito sejas do Senhor! Cumpri a palavra do Senhor."},
{v:14,t:"Samuel perguntou: Então que balido de ovelhas é este que me chega aos ouvidos, e que mugido de bois é este que estou ouvindo?"},
{v:15,t:"Saul respondeu: Trouxeram-nos de Amalec; porque o povo poupou o melhor das ovelhas e dos bois, para sacrificá-los ao Senhor teu Deus; o resto, votamo-lo ao extermínio.",n:"Saul atribui ao povo o que foi poupado e toma para si o que foi destruído. E diz o Senhor teu Deus, como se já não fosse o seu."},
{v:16,t:"Samuel disse a Saul: Basta! Vou anunciar-te o que o Senhor me disse esta noite. Ele respondeu: Fala."},
{v:17,t:"Samuel disse: Embora fosses pequeno aos teus próprios olhos, não te tornaste chefe das tribos de Israel? O Senhor te ungiu rei sobre Israel",np:1},
{v:18,t:"e te enviou numa missão, dizendo: Vai, vota ao extermínio esses pecadores, os amalecitas, e combate contra eles até exterminá-los."},
{v:19,t:"Por que, então, não ouviste a voz do Senhor, mas te lançaste sobre os despojos e fizeste o que é mau aos olhos do Senhor?"},
{v:20,t:"Saul respondeu a Samuel: Mas eu ouvi a voz do Senhor e segui o caminho pelo qual o Senhor me enviou; trouxe Agag, rei de Amalec, e votei Amalec ao extermínio."},
{v:21,t:"Mas o povo tomou dos despojos ovelhas e bois, o melhor do que fora votado ao extermínio, para sacrificá-los ao Senhor teu Deus em Guilgal."},
{v:22,t:"Samuel disse: Porventura o Senhor se compraz em holocaustos e sacrifícios, e não antes em que se obedeça à voz do Senhor? A obediência vale mais do que os sacrifícios, e a docilidade, mais do que a gordura dos carneiros.",n:"É a doutrina dos profetas: Oseias 6,6, que Jesus cita — quero misericórdia, e não sacrifício —, e o Salmo 40. O culto não substitui a obediência."},
{v:23,t:"A rebeldia é como o pecado de adivinhação, e a obstinação é como o crime de idolatria. Porque rejeitaste a palavra do Senhor, também ele te rejeitou como rei.",n:"A adivinhação e a idolatria eram, para Israel, o ápice da infidelidade. Samuel as põe no mesmo plano que a desobediência de um rei piedoso."},
{v:24,t:"Saul disse a Samuel: Pequei, porque transgredi a ordem do Senhor e as tuas palavras: tive medo do povo e cedi à sua voz.",np:1},
{v:25,t:"Mas agora, peço-te, perdoa o meu pecado e volta comigo, para que eu adore o Senhor."},
{v:26,t:"Samuel respondeu a Saul: Não voltarei contigo, porque rejeitaste a palavra do Senhor, e o Senhor te rejeitou, para que não sejas mais rei sobre Israel."},
{v:27,t:"Quando Samuel se voltou para ir embora, Saul agarrou a orla do seu manto, que se rasgou."},
{v:28,t:"Samuel lhe disse: Hoje o Senhor rasgou de ti o reino de Israel e o entregou a outro, melhor do que tu.",n:"O manto rasgado torna-se sinal profético, como o de Aías, que rasgará o seu manto em doze pedaços diante de Jeroboão (1 Reis 11,30)."},
{v:29,t:"A Glória de Israel não mente nem se arrepende; porque não é um homem, para se arrepender.",n:"Glória de Israel é um título de Deus. O capítulo diz que Deus se arrependeu (15,11.35) e que não se arrepende: a linguagem humana tenta exprimir que Deus sofre com a infidelidade do homem, mas não muda os seus desígnios."},
{v:30,t:"Saul disse: Pequei; mas honra-me agora diante dos anciãos do meu povo e diante de Israel, e volta comigo, para que eu adore o Senhor teu Deus.",n:"O que Saul teme agora é perder a face diante do povo."},
{v:31,t:"Samuel voltou, acompanhando Saul, e Saul adorou o Senhor."},
{v:32,t:"Samuel disse: Trazei-me Agag, rei de Amalec. Agag foi levado à sua presença, tremendo, e disse: Certamente passou a amargura da morte!",np:1,n:"O sentido é incerto: Agag pensa estar salvo, ou já sente a morte próxima. A palavra hebraica traduzida por tremendo pode significar também alegre, ou acorrentado."},
{v:33,t:"Samuel disse: Assim como a tua espada privou de filhos as mulheres, assim a tua mãe será privada de filho entre as mulheres. E Samuel despedaçou Agag diante do Senhor, em Guilgal."},
{v:34,t:"Samuel foi para Ramá, e Saul subiu para sua casa, em Gabaá de Saul.",np:1},
{v:35,t:"Samuel não tornou a ver Saul até o dia da sua morte; mas Samuel chorava por Saul, porque o Senhor se arrependera de ter constituído Saul rei sobre Israel.",n:"Não tornou a ver: não o visitou mais como profeta. Em 19,24 Saul irá ao encontro de Samuel. O luto de Samuel mostra o seu afeto pelo rei rejeitado."}
];

window.TEXTOS_SEED["1samuel"][16] = [
{s:"A unção de Davi"},
{v:1,t:"O Senhor disse a Samuel: Até quando chorarás por Saul, se eu o rejeitei, para que não reine mais sobre Israel? Enche de óleo o teu chifre e vai; eu te envio a Jessé, o belemita, porque escolhi para mim um rei entre os seus filhos."},
{v:2,t:"Samuel respondeu: Como irei? Saul o saberá e me matará. O Senhor disse: Leva contigo uma novilha e dize: Vim oferecer um sacrifício ao Senhor."},
{v:3,t:"Convidarás Jessé para o sacrifício, e eu te mostrarei o que deves fazer: ungirás aquele que eu te indicar."},
{v:4,t:"Samuel fez o que o Senhor lhe dissera e foi a Belém. Os anciãos da cidade vieram ao seu encontro, assustados, e perguntaram: A tua vinda é de paz?",np:1,n:"A visita inesperada do profeta, depois da ruptura com o rei, podia trazer um julgamento."},
{v:5,t:"Ele respondeu: É de paz; vim oferecer um sacrifício ao Senhor. Santificai-vos e vinde comigo ao sacrifício. E ele santificou Jessé e os seus filhos e convidou-os para o sacrifício."},
{v:6,t:"Quando entraram, Samuel viu Eliab e pensou: Certamente está aqui, diante do Senhor, o seu ungido!",np:1},
{v:7,t:"Mas o Senhor disse a Samuel: Não olhes para a sua aparência nem para a sua grande estatura, porque eu o rejeitei. Não julgo como o homem julga: o homem vê as aparências, mas o Senhor vê o coração.",n:"É o centro do capítulo. Saul era alto e belo; Deus escolhe agora pelo coração. Mas o texto dirá, logo depois, que Davi também era belo: Deus não despreza a beleza, apenas não se fia nela."},
{v:8,t:"Jessé chamou Abinadab e o fez passar diante de Samuel, que disse: Também a este o Senhor não escolheu."},
{v:9,t:"Jessé fez passar Samá, e Samuel disse: Também a este o Senhor não escolheu."},
{v:10,t:"Jessé fez passar assim sete de seus filhos diante de Samuel, e Samuel disse a Jessé: O Senhor não escolheu nenhum destes."},
{v:11,t:"Samuel perguntou a Jessé: São estes todos os teus filhos? Ele respondeu: Ainda falta o mais novo, que está apascentando as ovelhas. Samuel disse a Jessé: Manda buscá-lo, porque não nos sentaremos à mesa enquanto ele não chegar.",n:"O mais novo, o pastor, nem fora chamado: é o escolhido. O menor dos filhos, como José, como Gedeão; e o pastor do rebanho será o pastor do povo."},
{v:12,t:"Jessé mandou buscá-lo. Era ruivo, de belo aspecto e de rosto formoso. O Senhor disse: Levanta-te e unge-o: é este.",np:1},
{v:13,t:"Samuel tomou o chifre de óleo e ungiu-o no meio de seus irmãos; e, daquele dia em diante, o Espírito do Senhor apoderou-se de Davi. Samuel levantou-se e foi para Ramá.",n:"Davi, que quer dizer talvez amado, é nomeado aqui pela primeira vez, no momento em que recebe o Espírito."},
{s:"Davi a serviço de Saul"},
{v:14,t:"O Espírito do Senhor retirou-se de Saul, e um espírito mau, vindo do Senhor, o atormentava.",np:1,n:"O Espírito passa de Saul para Davi. A Bíblia atribui tudo a Deus, até o mal que ele permite: o espírito mau é a melancolia, talvez a loucura, que se apodera de Saul. A música era o remédio conhecido."},
{v:15,t:"Os servos de Saul disseram-lhe: Um espírito mau, vindo de Deus, te atormenta."},
{v:16,t:"Ordene o nosso senhor, e os servos que estão diante de ti procurarão um homem que saiba tocar a cítara; e, quando o espírito mau, vindo de Deus, se apoderar de ti, ele tocará com a sua mão, e te sentirás aliviado."},
{v:17,t:"Saul disse aos seus servos: Procurai-me um homem que toque bem e trazei-o a mim."},
{v:18,t:"Um dos servos tomou a palavra e disse: Conheço um filho de Jessé, o belemita, que sabe tocar; é valente e guerreiro, fala com prudência, tem boa aparência, e o Senhor está com ele."},
{v:19,t:"Saul enviou mensageiros a Jessé, dizendo: Manda-me teu filho Davi, que está com o rebanho."},
{v:20,t:"Jessé tomou um jumento carregado de pão, um odre de vinho e um cabrito, e enviou-os a Saul por meio de seu filho Davi."},
{v:21,t:"Davi chegou junto de Saul e entrou ao seu serviço. Saul afeiçoou-se muito a ele, e Davi tornou-se o seu escudeiro."},
{v:22,t:"Saul mandou dizer a Jessé: Que Davi fique ao meu serviço, porque ganhou a minha simpatia."},
{v:23,t:"Assim, sempre que o espírito vindo de Deus se apoderava de Saul, Davi tomava a cítara e tocava com a sua mão; Saul se acalmava e se sentia melhor, e o espírito mau o deixava."}
];

window.TEXTOS_SEED["1samuel"][17] = [
{s:"Golias desafia Israel"},
{v:1,t:"Os filisteus reuniram as suas tropas para a guerra, concentraram-se em Soco de Judá e acamparam entre Soco e Azeca, em Efes-Domim."},
{v:2,t:"Saul e os homens de Israel também se reuniram, acamparam no vale do Terebinto e dispuseram-se em linha de batalha contra os filisteus."},
{v:3,t:"Os filisteus estavam num monte, de um lado, e Israel estava num monte, do outro lado; e o vale ficava entre eles."},
{v:4,t:"Saiu então do acampamento dos filisteus um campeão chamado Golias, de Gat, que tinha seis côvados e um palmo de altura.",np:1,n:"Cerca de três metros. A versão grega e um manuscrito de Qumran dizem quatro côvados e um palmo, cerca de dois metros: já um gigante para a época. Campeão, à letra o homem do meio: o que combate entre os dois exércitos."},
{v:5,t:"Trazia na cabeça um capacete de bronze e vestia uma couraça de escamas; o peso da couraça era de cinco mil siclos de bronze.",n:"Uns cinquenta e sete quilos."},
{v:6,t:"Tinha caneleiras de bronze nas pernas e uma cimitarra de bronze às costas."},
{v:7,t:"A haste da sua lança era como o cilindro de um tear, e a ponta da lança pesava seiscentos siclos de ferro. Diante dele ia o seu escudeiro.",n:"A ponta de ferro pesava perto de sete quilos. O ferro, raro em Israel, sublinha a superioridade dos filisteus."},
{v:8,t:"Ele parou e gritou às fileiras de Israel: Por que saístes em linha de batalha? Não sou eu o filisteu, e vós, servos de Saul? Escolhei um homem dentre vós, e que desça para um combate singular!"},
{v:9,t:"Se ele puder lutar comigo e me matar, seremos vossos servos; mas, se eu o vencer e o matar, sereis nossos servos e nos servireis."},
{v:10,t:"E o filisteu disse: Hoje desafio as fileiras de Israel: dai-me um homem, e lutemos a sós!"},
{v:11,t:"Ouvindo essas palavras do filisteu, Saul e todo o Israel ficaram consternados e tiveram muito medo."},
{s:"Davi no acampamento"},
{v:12,t:"Davi era filho daquele efrateu de Belém de Judá, de quem se falou acima, que se chamava Jessé; tinha oito filhos, e no tempo de Saul era um homem velho, de idade avançada.",np:1,n:"Os versículos 12 a 31, como 17,55 a 18,5, faltam no principal manuscrito da versão grega. Parecem conservar uma segunda narrativa da chegada de Davi à corte, na qual Saul ainda não o conhece: o redator juntou as duas tradições sem harmonizá-las."},
{v:13,t:"Os três filhos mais velhos de Jessé tinham seguido Saul na guerra; os nomes dos três filhos que tinham partido para a guerra eram: Eliab, o primogênito, o segundo, Abinadab, e o terceiro, Samá."},
{v:14,t:"Davi era o mais novo. Enquanto os três mais velhos seguiam Saul,"},
{v:15,t:"Davi ia e vinha da corte de Saul, para apascentar o rebanho de seu pai em Belém."},
{v:16,t:"O filisteu avançava de manhã e de tarde, e apresentou-se assim durante quarenta dias."},
{v:17,t:"Jessé disse a seu filho Davi: Toma para teus irmãos este efá de grão torrado e estes dez pães, e leva-os depressa aos teus irmãos, no acampamento.",np:1},
{v:18,t:"Estes dez queijos, leva-os ao comandante de mil. Verás se os teus irmãos estão bem e trarás deles algum sinal."},
{v:19,t:"Saul, eles e todos os homens de Israel estavam no vale do Terebinto, em guerra contra os filisteus."},
{v:20,t:"Davi levantou-se de madrugada, deixou o rebanho com um guarda, tomou a carga e partiu, como Jessé lhe ordenara. Chegou ao acampamento no momento em que o exército saía para a linha de batalha, lançando o grito de guerra.",np:1},
{v:21,t:"Israel e os filisteus puseram-se em linha, fileira contra fileira."},
{v:22,t:"Davi deixou a carga nas mãos do guarda das bagagens, correu à linha de batalha e foi perguntar aos seus irmãos como estavam."},
{v:23,t:"Enquanto falava com eles, eis que o campeão, o filisteu de Gat chamado Golias, subiu das fileiras dos filisteus e repetiu as mesmas palavras; e Davi as ouviu."},
{v:24,t:"Todos os homens de Israel, quando viram aquele homem, fugiram diante dele, cheios de medo."},
{v:25,t:"Um dos homens de Israel dizia: Vistes esse homem que sobe? Sobe para desafiar Israel. A quem o matar, o rei cumulará de grandes riquezas, lhe dará a sua filha e isentará de impostos a casa de seu pai em Israel."},
{v:26,t:"Davi perguntou aos homens que estavam junto dele: Que se fará ao homem que matar esse filisteu e tirar a afronta de Israel? Quem é esse filisteu incircunciso, para desafiar as fileiras do Deus vivo?",n:"As primeiras palavras de Davi no livro: o que o move é a honra do Deus vivo."},
{v:27,t:"O povo repetiu-lhe as mesmas palavras, dizendo: Isso é o que se fará ao homem que o matar."},
{v:28,t:"Eliab, seu irmão mais velho, ouviu-o falar com os homens e irritou-se contra Davi, dizendo: Por que desceste? E com quem deixaste aquelas poucas ovelhas no deserto? Conheço o teu orgulho e a malícia do teu coração: desceste para ver a batalha.",np:1},
{v:29,t:"Davi respondeu: Que fiz eu agora? Foi só uma pergunta!"},
{v:30,t:"Afastou-se dele, dirigiu-se a outro e fez a mesma pergunta; e o povo deu-lhe a mesma resposta."},
{s:"Davi vence Golias"},
{v:31,t:"As palavras que Davi dissera foram ouvidas e referidas a Saul.",np:1},
{v:32,t:"Levado à presença de Saul, Davi lhe disse: Que ninguém perca o ânimo por causa dele: teu servo irá lutar contra esse filisteu."},
{v:33,t:"Saul disse a Davi: Não podes enfrentar esse filisteu e lutar contra ele, porque és apenas um rapaz, e ele é homem de guerra desde a juventude."},
{v:34,t:"Davi respondeu a Saul: Teu servo apascentava o rebanho de seu pai; quando vinha um leão ou um urso e levava uma ovelha do rebanho,"},
{v:35,t:"eu ia atrás dele, feria-o e arrancava-a da sua boca; e, se ele se levantava contra mim, eu o agarrava pela queixada, o feria e o matava."},
{v:36,t:"Teu servo matou o leão e o urso; esse filisteu incircunciso será como um deles, porque ousou desafiar as fileiras do Deus vivo."},
{v:37,t:"E Davi acrescentou: O Senhor, que me livrou das garras do leão e das garras do urso, ele me livrará da mão desse filisteu. Saul disse a Davi: Vai, e o Senhor esteja contigo."},
{v:38,t:"Saul vestiu Davi com a sua própria armadura, pôs-lhe na cabeça um capacete de bronze e o revestiu de uma couraça.",np:1},
{v:39,t:"Davi cingiu a espada de Saul por cima da armadura e tentou andar, porque não estava acostumado. Então Davi disse a Saul: Não posso andar com isto, porque não estou acostumado. E tirou tudo aquilo;",n:"Davi não vence com as armas do rei. A cena é quase cômica: o rapaz afundado na armadura do homem mais alto de Israel."},
{v:40,t:"tomou na mão o seu cajado, escolheu no riacho cinco pedras bem lisas e colocou-as no seu alforje de pastor, que lhe servia de sacola para as pedras; e, com a funda na mão, avançou contra o filisteu."},
{v:41,t:"O filisteu vinha avançando e aproximando-se de Davi, precedido do seu escudeiro.",np:1},
{v:42,t:"Quando o filisteu olhou e viu Davi, desprezou-o, porque era apenas um rapaz, ruivo e de belo aspecto."},
{v:43,t:"O filisteu disse a Davi: Sou eu um cão, para vires contra mim com um cajado? E o filisteu amaldiçoou Davi pelos seus deuses."},
{v:44,t:"Disse ainda o filisteu a Davi: Vem até mim, e darei a tua carne às aves do céu e aos animais selvagens."},
{v:45,t:"Davi respondeu ao filisteu: Tu vens contra mim com espada, lança e cimitarra; eu, porém, vou contra ti em nome do Senhor dos exércitos, o Deus das fileiras de Israel, que tu desafiaste.",n:"É a frase central do capítulo: a força do filisteu está nas armas; a de Davi, no nome do Senhor."},
{v:46,t:"Hoje o Senhor te entregará nas minhas mãos; eu te ferirei e te cortarei a cabeça, e darei hoje o teu cadáver e os cadáveres do exército dos filisteus às aves do céu e aos animais selvagens, para que toda a terra saiba que há um Deus em Israel,"},
{v:47,t:"e toda esta assembleia saiba que não é com espada nem com lança que o Senhor salva: porque a guerra é do Senhor, e ele vos entregará nas nossas mãos."},
{v:48,t:"Quando o filisteu se pôs em movimento e avançou ao encontro de Davi, Davi correu depressa para a linha de batalha, ao encontro do filisteu.",np:1},
{v:49,t:"Meteu a mão no alforje, tirou uma pedra e atirou-a com a funda; atingiu o filisteu na testa, a pedra cravou-se na sua testa, e ele caiu de rosto em terra."},
{v:50,t:"Assim Davi venceu o filisteu com a funda e a pedra; feriu o filisteu e o matou. E, como Davi não tinha espada na mão,",n:"Este versículo, que falta na versão grega, parece uma conclusão antecipada: diz que Davi matou o filisteu sem espada, e o seguinte, que o matou com a espada do próprio gigante."},
{v:51,t:"correu, pôs-se de pé sobre o filisteu, tomou-lhe a espada, tirou-a da bainha, acabou de matá-lo e com ela cortou-lhe a cabeça. Os filisteus, vendo que o seu campeão estava morto, fugiram."},
{v:52,t:"Os homens de Israel e de Judá levantaram-se, lançaram o grito de guerra e perseguiram os filisteus até a entrada de Gat e até as portas de Acaron. Os feridos dos filisteus caíram pelo caminho de Saraim até Gat e até Acaron."},
{v:53,t:"Os filhos de Israel voltaram da perseguição aos filisteus e saquearam o seu acampamento."},
{v:54,t:"Davi tomou a cabeça do filisteu e levou-a para Jerusalém; e as armas dele, pô-las na sua tenda.",n:"Jerusalém só será conquistada por Davi mais tarde (2 Samuel 5): o narrador antecipa. A espada de Golias aparecerá guardada no santuário de Nob (21,9)."},
{s:"Davi diante de Saul"},
{v:55,t:"Quando Saul viu Davi sair ao encontro do filisteu, perguntou a Abner, chefe do exército: Abner, de quem é filho este jovem? Abner respondeu: Pela tua vida, ó rei, não sei.",np:1,n:"Saul não conhece Davi, que no capítulo anterior era o seu músico e escudeiro: é o sinal das duas tradições juntadas pelo redator."},
{v:56,t:"O rei disse: Informa-te de quem é filho este rapaz."},
{v:57,t:"Quando Davi voltou, depois de matar o filisteu, Abner tomou-o e levou-o à presença de Saul; e Davi tinha na mão a cabeça do filisteu."},
{v:58,t:"Saul perguntou-lhe: De quem és filho, rapaz? Davi respondeu: Sou filho do teu servo Jessé, o belemita."}
];

window.TEXTOS_SEED["1samuel"][18] = [
{s:"Jônatas e Davi"},
{v:1,t:"Quando Davi acabou de falar com Saul, a alma de Jônatas apegou-se à alma de Davi, e Jônatas o amou como a si mesmo.",n:"Como a sua própria alma: a amizade de Jônatas e Davi ficou como o modelo bíblico da amizade fiel, que resiste ao interesse e à política."},
{v:2,t:"Naquele dia Saul o tomou consigo e não o deixou voltar para a casa de seu pai."},
{v:3,t:"Jônatas e Davi fizeram uma aliança, porque Jônatas o amava como a si mesmo."},
{v:4,t:"Jônatas tirou o manto que vestia e o deu a Davi, e também a sua armadura, até a espada, o arco e o cinturão.",n:"O gesto tem valor simbólico: o herdeiro do trono entrega as suas insígnias àquele que reinará em seu lugar."},
{v:5,t:"Davi saía a todas as missões que Saul lhe confiava e era bem-sucedido; e Saul pô-lo à frente dos homens de guerra. Ele agradava a todo o povo, e também aos servos de Saul."},
{s:"O ciúme de Saul"},
{v:6,t:"Quando voltavam, ao regressar Davi da vitória sobre o filisteu, as mulheres de todas as cidades de Israel saíram ao encontro do rei Saul, cantando e dançando, com tamborins, com cantos de alegria e com sistros.",np:1},
{v:7,l:["E as mulheres, dançando, cantavam em coro:","Saul matou os seus milhares,","e Davi, os seus dez milhares."],n:"No paralelismo hebraico, milhares e dez milhares querem dizer apenas muitos e muitíssimos; mas Saul entende o canto à letra. Os filisteus conhecerão este canto (21,12; 29,5)."},
{v:8,t:"Saul ficou muito irritado; aquelas palavras desagradaram-lhe, e ele disse: A Davi deram dez milhares, e a mim deram milhares. Só lhe falta o reino!"},
{v:9,t:"E daquele dia em diante Saul passou a olhar Davi com desconfiança."},
{v:10,t:"No dia seguinte, o espírito mau, vindo de Deus, apoderou-se de Saul, e ele delirava no meio da casa. Davi tocava com a sua mão, como todos os dias, e Saul tinha na mão a lança.",np:1,n:"Delirava: o verbo hebraico é o mesmo de profetizar (10,10). O êxtase que foi sinal de Deus tornou-se agora doença."},
{v:11,t:"Saul arremessou a lança, pensando: Vou cravar Davi na parede! Mas Davi esquivou-se dele duas vezes."},
{v:12,t:"Saul tinha medo de Davi, porque o Senhor estava com ele e se tinha retirado de Saul."},
{v:13,t:"Por isso Saul o afastou de si e o nomeou chefe de mil homens; e Davi saía e entrava à frente do povo.",n:"Saía e entrava: comandava as expedições. Saul pensa afastá-lo; mas assim o torna ainda mais conhecido do povo."},
{v:14,t:"Davi era bem-sucedido em todos os seus caminhos, e o Senhor estava com ele."},
{v:15,t:"Vendo Saul que ele era tão bem-sucedido, começou a temê-lo;"},
{v:16,t:"mas todo o Israel e Judá amavam Davi, porque era ele quem saía e entrava à frente deles."},
{s:"Davi, genro do rei"},
{v:17,t:"Saul disse a Davi: Aqui está Merob, a minha filha mais velha; eu a darei a ti por mulher; basta que me sirvas com valentia e combatas as guerras do Senhor. Mas Saul pensava: Que não seja a minha mão a feri-lo, mas a mão dos filisteus.",np:1,n:"Saul devia a filha a Davi, como prêmio prometido a quem matasse Golias (17,25); agora a oferece com novas condições."},
{v:18,t:"Davi respondeu a Saul: Quem sou eu, e que é a minha vida, e a família de meu pai em Israel, para que eu venha a ser genro do rei?"},
{v:19,t:"Mas, quando chegou o tempo em que Merob, filha de Saul, devia ser dada a Davi, foi dada por mulher a Adriel, de Meolá."},
{v:20,t:"Mas Micol, a outra filha de Saul, amava Davi; contaram isso a Saul, e a coisa lhe agradou.",np:1,n:"É a única vez que a Bíblia diz que uma mulher amava um homem. Micol será vítima dos cálculos do pai e, mais tarde, dos do marido."},
{v:21,t:"Saul disse: Eu a darei a ele, para que ela lhe seja uma armadilha e caia sobre ele a mão dos filisteus. E Saul disse a Davi pela segunda vez: Hoje serás meu genro."},
{v:22,t:"E Saul deu ordem aos seus servos: Falai a Davi em particular e dizei-lhe: O rei gosta de ti, e todos os seus servos te querem bem; aceita, pois, ser genro do rei."},
{v:23,t:"Os servos de Saul repetiram essas palavras aos ouvidos de Davi, e Davi disse: Parece-vos pouca coisa ser genro do rei? Eu sou um homem pobre e sem importância.",n:"Davi alega que não pode pagar o dote, o mohar, que o noivo devia dar à família da noiva, e que para a filha de um rei seria altíssimo."},
{v:24,t:"Os servos de Saul referiram-lhe: Foi isso que Davi disse."},
{v:25,t:"Saul disse: Assim direis a Davi: O rei não quer outro dote senão cem prepúcios de filisteus, para se vingar dos inimigos do rei. Saul pensava fazer Davi cair nas mãos dos filisteus.",n:"Os prepúcios provavam que os mortos eram filisteus, povo que não praticava a circuncisão."},
{v:26,t:"Os servos de Saul referiram essas palavras a Davi, e Davi achou bem tornar-se genro do rei."},
{v:27,t:"Antes que o prazo se esgotasse, Davi partiu com os seus homens e matou duzentos filisteus; trouxe os seus prepúcios e os entregou em número completo ao rei, para se tornar seu genro. E Saul deu-lhe por mulher a sua filha Micol.",n:"Duzentos: Davi paga o dobro. A versão grega diz cem, como em 2 Samuel 3,14."},
{v:28,t:"Saul viu e compreendeu que o Senhor estava com Davi; e Micol, filha de Saul, o amava.",np:1},
{v:29,t:"Então Saul teve ainda mais medo de Davi, e tornou-se seu inimigo para sempre."},
{v:30,t:"Os chefes dos filisteus saíam a campo; e, todas as vezes que saíam, Davi tinha mais êxito do que todos os servos de Saul, e o seu nome tornou-se muito célebre."}
];

window.TEXTOS_SEED["1samuel"][19] = [
{s:"Jônatas intercede por Davi"},
{v:1,t:"Saul falou a seu filho Jônatas e a todos os seus servos em matar Davi. Mas Jônatas, filho de Saul, gostava muito de Davi,"},
{v:2,t:"e avisou Davi, dizendo: Meu pai Saul procura matar-te. Por isso, toma cuidado amanhã de manhã: fica num lugar retirado e esconde-te."},
{v:3,t:"Eu sairei e ficarei junto de meu pai no campo onde estiveres; falarei de ti a meu pai e, se descobrir alguma coisa, te avisarei."},
{v:4,t:"Jônatas falou bem de Davi a seu pai Saul e disse-lhe: Que o rei não peque contra o seu servo Davi, porque ele não pecou contra ti, e as suas obras te foram muito úteis.",np:1},
{v:5,t:"Ele arriscou a vida e matou o filisteu, e o Senhor deu uma grande vitória a todo o Israel; tu viste e te alegraste. Por que, pois, pecarias contra sangue inocente, matando Davi sem motivo?"},
{v:6,t:"Saul ouviu a voz de Jônatas, aplacou-se e jurou: Pela vida do Senhor, ele não morrerá."},
{v:7,t:"Jônatas chamou Davi e contou-lhe todas essas palavras. Depois levou Davi a Saul, e Davi ficou a seu serviço como antes."},
{s:"Davi foge de Saul"},
{v:8,t:"Recomeçou a guerra, e Davi saiu a combater contra os filisteus; infligiu-lhes uma grande derrota, e eles fugiram diante dele.",np:1},
{v:9,t:"Então o espírito mau, vindo do Senhor, apoderou-se de Saul, quando estava sentado em sua casa com a lança na mão, enquanto Davi tocava com a sua mão."},
{v:10,t:"Saul procurou cravar Davi na parede com a lança; mas Davi esquivou-se de Saul, e a lança, sem feri-lo, cravou-se na parede. Davi fugiu e salvou-se naquela noite."},
{v:11,t:"Saul enviou os seus guardas à casa de Davi, para vigiá-lo e matá-lo pela manhã. Mas Micol, sua mulher, avisou Davi, dizendo: Se não salvares a tua vida esta noite, amanhã estarás morto.",np:1,n:"O Salmo 59, segundo o seu título, foi composto nesta ocasião."},
{v:12,t:"E Micol fez Davi descer pela janela; ele partiu, fugiu e salvou-se."},
{v:13,t:"Micol tomou o terafim e o pôs na cama, colocou-lhe na cabeça uma pele de cabra e cobriu-o com uma roupa.",n:"O terafim era uma imagem doméstica, como as que Raquel escondeu de seu pai (Gênesis 31,19); o de Micol devia ter tamanho humano. A sua presença na casa de Davi mostra quanto essas práticas estavam enraizadas."},
{v:14,t:"Quando Saul enviou mensageiros para prender Davi, ela disse: Está doente."},
{v:15,t:"Saul tornou a enviar os mensageiros para verem Davi, dizendo: Trazei-o a mim na cama, para que eu o mate."},
{v:16,t:"Os mensageiros entraram, e eis que na cama estava o terafim, com a pele de cabra na cabeça."},
{v:17,t:"Saul disse a Micol: Por que me enganaste assim e deixaste fugir o meu inimigo? Micol respondeu a Saul: Ele me disse: Deixa-me ir, senão te mato."},
{s:"Saul de novo entre os profetas"},
{v:18,t:"Davi fugiu, salvou-se e foi ter com Samuel em Ramá, e contou-lhe tudo o que Saul lhe tinha feito. Depois ele e Samuel foram morar em Naiot.",np:1,n:"Naiot quer dizer talvez as habitações: o lugar onde vivia o grupo de profetas, em Ramá."},
{v:19,t:"Informaram a Saul: Davi está em Naiot, em Ramá."},
{v:20,t:"Saul enviou mensageiros para prender Davi. Quando eles viram o grupo dos profetas em transe, e Samuel de pé à frente deles, o Espírito de Deus veio também sobre os mensageiros, e eles também entraram em transe."},
{v:21,t:"Informaram Saul, e ele enviou outros mensageiros, que também entraram em transe. Saul enviou pela terceira vez mensageiros, e estes também entraram em transe."},
{v:22,t:"Então ele mesmo foi a Ramá e chegou à grande cisterna que há em Secu; e perguntou: Onde estão Samuel e Davi? Responderam-lhe: Estão em Naiot, em Ramá.",n:"Secu, como diz o hebraico; a Nova Vulgata, como a antiga Vulgata, lê Soco."},
{v:23,t:"Dali foi para Naiot, em Ramá; e o Espírito de Deus veio também sobre ele, e ele foi caminhando em transe até chegar a Naiot, em Ramá."},
{v:24,t:"Também ele tirou as suas vestes e entrou em transe diante de Samuel; e ficou caído, nu, todo aquele dia e toda aquela noite. Daí vem o provérbio: Também Saul está entre os profetas?",n:"Segunda explicação do provérbio (ver 10,12). Aqui o sentido é irônico: o Espírito que o fez rei agora o desarma e o humilha diante de Samuel."}
];

window.TEXTOS_SEED["1samuel"][20] = [
{s:"A aliança de Davi e Jônatas"},
{v:1,t:"Davi fugiu de Naiot, em Ramá, e foi dizer a Jônatas: Que fiz eu? Qual é a minha culpa, e qual o meu pecado contra teu pai, para que ele procure tirar-me a vida?"},
{v:2,t:"Jônatas lhe respondeu: Longe disso! Não morrerás. Meu pai não faz coisa alguma, grande ou pequena, sem me dizer; por que me esconderia meu pai esta coisa? Não é possível."},
{v:3,t:"Davi respondeu: Teu pai sabe muito bem que gozo da tua amizade, e pensou: Que Jônatas não saiba disto, para que não se aflija. Mas, pela vida do Senhor e pela tua vida, entre mim e a morte há apenas um passo."},
{v:4,t:"Jônatas disse a Davi: Que desejas que eu faça por ti?"},
{v:5,t:"Davi disse a Jônatas: Amanhã é lua nova, e eu costumo sentar-me à mesa com o rei. Deixa-me ir, e me esconderei no campo até a tarde do terceiro dia.",n:"A lua nova era festa religiosa, com refeição sagrada; a ausência de Davi à mesa do rei seria notada."},
{v:6,t:"Se teu pai perguntar por mim, tu lhe dirás: Davi pediu-me com insistência que o deixasse ir depressa a Belém, sua cidade, porque ali se celebra o sacrifício anual de toda a sua família."},
{v:7,t:"Se ele disser: Está bem, o teu servo estará em paz; mas, se ele se irritar, sabe que a minha perda está decidida por ele."},
{v:8,t:"Mostra, pois, a tua bondade para com o teu servo, porque fizeste o teu servo entrar contigo numa aliança do Senhor. Mas, se há em mim alguma culpa, mata-me tu mesmo: por que me levarias a teu pai?"},
{v:9,t:"Jônatas disse: Longe de ti tal pensamento! Se eu soubesse com certeza que meu pai decidiu a tua perda, como não te avisaria?"},
{v:10,t:"Davi perguntou a Jônatas: Quem me avisará, se teu pai te responder com dureza?"},
{v:11,t:"Jônatas disse a Davi: Vem, saiamos ao campo. E os dois saíram ao campo.",np:1},
{v:12,t:"Jônatas disse a Davi: Pelo Senhor, Deus de Israel! Amanhã ou depois de amanhã, a esta hora, sondarei o pensamento de meu pai; e, se ele estiver bem disposto para com Davi, e eu não mandar logo avisar-te,"},
{v:13,t:"que o Senhor faça isto a Jônatas e mais aquilo! Mas, se meu pai persistir em querer o teu mal, também te farei saber e te deixarei partir, para que vás em paz. E o Senhor esteja contigo, como esteve com meu pai."},
{v:14,t:"E, se eu ainda estiver vivo, usarás comigo a bondade do Senhor; e, se eu morrer,"},
{v:15,t:"não retirarás jamais a tua bondade da minha casa, nem mesmo quando o Senhor tiver exterminado da face da terra todos os inimigos de Davi.",n:"Davi cumprirá a promessa acolhendo Mefiboset, filho de Jônatas, à sua mesa (2 Samuel 9)."},
{v:16,t:"Assim Jônatas fez aliança com a casa de Davi, dizendo: Que o Senhor peça contas aos inimigos de Davi!"},
{v:17,t:"E Jônatas fez Davi jurar de novo, pelo amor que lhe tinha; porque o amava como a si mesmo."},
{v:18,t:"Jônatas disse-lhe: Amanhã é lua nova, e sentirão a tua falta,",np:1},
{v:19,t:"porque o teu lugar estará vazio. Depois de amanhã descerás depressa ao lugar onde te escondeste no dia daquele caso, e ficarás junto daquele monte de pedras."},
{v:20,t:"Eu atirarei três flechas para aquele lado, como se atirasse a um alvo."},
{v:21,t:"Depois mandarei o rapaz, dizendo: Vai buscar as flechas."},
{v:22,t:"Se eu disser ao rapaz: As flechas estão para cá de ti, apanha-as, vem, porque estás em paz e não há perigo algum, pela vida do Senhor. Mas, se eu disser ao rapaz: As flechas estão para lá de ti, vai-te, porque o Senhor te manda partir."},
{v:23,t:"Quanto à palavra que trocamos, eu e tu, o Senhor esteja entre mim e ti para sempre."},
{s:"A lua nova à mesa de Saul"},
{v:24,t:"Davi escondeu-se no campo. Chegou a lua nova, e o rei sentou-se à mesa para comer.",np:1},
{v:25,t:"O rei sentou-se, como de costume, no seu assento junto à parede; Jônatas sentou-se em frente, e Abner ao lado de Saul; e o lugar de Davi ficou vazio."},
{v:26,t:"Naquele dia Saul não disse nada, porque pensava: Aconteceu-lhe alguma coisa; não estará puro, certamente não se purificou.",n:"A refeição da lua nova era sagrada, e só podia participar dela quem estivesse ritualmente puro."},
{v:27,t:"No dia seguinte à lua nova, o segundo dia, o lugar de Davi continuava vazio; e Saul disse a seu filho Jônatas: Por que o filho de Jessé não veio comer, nem ontem nem hoje?",n:"O filho de Jessé: Saul não diz o nome de Davi, por desprezo."},
{v:28,t:"Jônatas respondeu a Saul: Davi pediu-me com insistência que o deixasse ir a Belém."},
{v:29,t:"Disse-me: Deixa-me ir, porque temos na cidade um sacrifício de família, e meu irmão mesmo me chamou; agora, pois, se gozo da tua amizade, deixa-me ir depressa ver meus irmãos. Por isso ele não veio à mesa do rei."},
{v:30,t:"Então Saul se inflamou de cólera contra Jônatas e lhe disse: Filho de uma mulher perversa e rebelde! Pensas que não sei que tomaste o partido do filho de Jessé, para vergonha tua e para vergonha da nudez de tua mãe?",np:1},
{v:31,t:"Enquanto o filho de Jessé viver sobre a terra, nem tu nem o teu reino estareis seguros. Manda, pois, agora mesmo buscá-lo e traze-o a mim, porque ele merece a morte.",n:"Saul vê com clareza o que Jônatas aceita de boa vontade: Davi tomará o lugar do herdeiro."},
{v:32,t:"Jônatas respondeu a seu pai Saul: Por que há de morrer? Que fez ele?"},
{v:33,t:"Então Saul arremessou a lança contra ele, para feri-lo; e Jônatas compreendeu que seu pai estava decidido a matar Davi."},
{v:34,t:"Jônatas levantou-se da mesa ardendo de cólera e não comeu nada no segundo dia da lua nova, porque estava aflito por causa de Davi e porque seu pai o tinha ultrajado."},
{s:"O sinal das flechas"},
{v:35,t:"Na manhã seguinte, Jônatas saiu ao campo, ao lugar combinado com Davi, e com ele um rapazinho.",np:1},
{v:36,t:"Disse ao rapaz: Corre e vai buscar as flechas que eu atirar. Enquanto o rapaz corria, ele atirou uma flecha para além dele."},
{v:37,t:"Quando o rapaz chegou ao lugar da flecha que Jônatas tinha atirado, Jônatas gritou atrás dele: A flecha não está mais adiante de ti?"},
{v:38,t:"E Jônatas gritou ainda atrás do rapaz: Depressa, apressa-te, não pares! O rapaz de Jônatas apanhou a flecha e voltou ao seu senhor,"},
{v:39,t:"sem entender coisa alguma; só Jônatas e Davi sabiam do que se tratava."},
{v:40,t:"Jônatas deu as suas armas ao rapaz e lhe disse: Vai, leva-as à cidade."},
{v:41,t:"Assim que o rapaz se foi, Davi levantou-se do lado do monte de pedras, caiu com o rosto por terra e prostrou-se três vezes. Depois beijaram-se e choraram juntos; e Davi chorou mais ainda.",np:1},
{v:42,t:"Jônatas disse a Davi: Vai em paz, pois ambos juramos em nome do Senhor, dizendo: O Senhor estará entre mim e ti, e entre a minha descendência e a tua descendência, para sempre."}
];

window.TEXTOS_SEED["1samuel"][21] = [
{s:"Davi em Nob"},
{v:1,t:"Davi levantou-se e partiu, e Jônatas voltou para a cidade."},
{v:2,t:"Davi foi a Nob, ter com o sacerdote Aquimelec. Aquimelec, assustado com a chegada de Davi, veio ao seu encontro e perguntou-lhe: Por que estás sozinho, e ninguém contigo?",np:1,n:"Nob, perto de Jerusalém, era então o santuário dos sacerdotes descendentes de Heli; Aquimelec é talvez o mesmo Aías de 14,3."},
{v:3,t:"Davi respondeu ao sacerdote Aquimelec: O rei encarregou-me de uma missão e me disse: Que ninguém saiba nada do assunto para o qual te envio, nem das ordens que te dei. Quanto aos meus homens, marquei encontro com eles em tal e tal lugar.",n:"Davi mente para obter ajuda; a mentira custará a vida aos sacerdotes de Nob (22,22)."},
{v:4,t:"Agora, pois, que tens à mão? Dá-me cinco pães, ou o que puderes encontrar."},
{v:5,t:"O sacerdote respondeu a Davi: Não tenho à mão pão comum, só pão consagrado; contanto que os teus homens se tenham abstido de mulheres."},
{v:6,t:"Davi respondeu ao sacerdote: Certamente; quanto a mulheres, temo-nos abstido desde anteontem. Sempre que parto em expedição, os corpos dos meus homens se conservam santos, ainda que se trate de uma viagem profana; quanto mais hoje estarão santos os seus corpos!",n:"A continência sexual era exigida dos combatentes da guerra santa e de quem tocava as coisas sagradas."},
{v:7,t:"O sacerdote deu-lhe então o pão consagrado, porque não havia ali outro pão senão os pães da proposição, que tinham sido retirados da presença do Senhor, para serem substituídos por pães quentes.",n:"Os doze pães da proposição ficavam expostos diante do Senhor e eram trocados todos os sábados; só os sacerdotes podiam comê-los (Levítico 24,5-9). Jesus lembrará este episódio para mostrar que a necessidade do homem está acima da regra ritual (Marcos 2,25-26)."},
{v:8,t:"Estava ali naquele dia, retido diante do Senhor, um dos servos de Saul, chamado Doeg, o edomita, chefe dos pastores de Saul.",n:"Retido diante do Senhor: talvez por um voto ou por uma purificação. A menção prepara o capítulo seguinte."},
{v:9,t:"Davi disse a Aquimelec: Não tens aqui à mão uma lança ou uma espada? Não trouxe comigo nem a minha espada nem as minhas armas, porque a missão do rei era urgente.",np:1},
{v:10,t:"O sacerdote respondeu: Aqui está a espada de Golias, o filisteu que mataste no vale do Terebinto; está envolta num pano, atrás do efod. Se quiseres levá-la, leva-a, porque aqui não há outra senão esta. Davi disse: Não há outra igual; dá-me essa."},
{s:"Davi junto de Aquis, rei de Gat"},
{v:11,t:"Naquele dia, Davi levantou-se e fugiu de Saul, e foi ter com Aquis, rei de Gat.",np:1,n:"Davi refugia-se entre os inimigos, e justamente em Gat, a cidade de Golias, levando a espada do gigante."},
{v:12,t:"Os servos de Aquis disseram-lhe: Não é este Davi, o rei da terra? Não é a ele que cantavam em coro, dizendo: Saul matou os seus milhares, e Davi, os seus dez milhares?"},
{v:13,t:"Davi guardou essas palavras no coração e teve muito medo de Aquis, rei de Gat."},
{v:14,t:"Então fingiu-se louco diante deles: fazia-se de insano nas mãos deles, batia contra os batentes da porta e deixava a saliva escorrer pela barba.",n:"Os títulos dos Salmos 34 e 56 lembram este episódio. Os loucos eram temidos e respeitados, como tocados pela divindade."},
{v:15,t:"Aquis disse aos seus servos: Vedes que este homem está louco. Por que o trouxestes a mim?"},
{v:16,t:"Falta-me acaso gente louca, para que me trouxésseis este, para fazer loucuras diante de mim? Há de entrar este homem em minha casa?"}
];

window.TEXTOS_SEED["1samuel"][22] = [
{s:"Davi chefe de um bando"},
{v:1,t:"Davi partiu dali e refugiou-se na caverna de Odolam. Seus irmãos e toda a casa de seu pai souberam disso e desceram até lá para junto dele."},
{v:2,t:"Juntaram-se a ele todos os que estavam em apuros, os endividados e os descontentes, e ele se tornou o seu chefe. Havia com ele cerca de quatrocentos homens.",n:"Um bando de marginalizados: Davi começa como Jefté, à frente de homens sem lugar na sociedade."},
{v:3,t:"Dali Davi foi a Masfa de Moab e disse ao rei de Moab: Permite que meu pai e minha mãe fiquem convosco, até que eu saiba o que Deus fará de mim.",np:1,n:"Davi descendia de Rute, a moabita (Rute 4,17): talvez por isso confia os pais ao rei de Moab."},
{v:4,t:"E deixou-os na presença do rei de Moab; e eles ficaram com ele todo o tempo em que Davi esteve no refúgio."},
{v:5,t:"O profeta Gad disse a Davi: Não fiques no refúgio; parte e vai para a terra de Judá. Davi partiu e foi para o bosque de Haret.",n:"Gad acompanhará Davi até a velhice (2 Samuel 24,11)."},
{s:"O massacre dos sacerdotes de Nob"},
{v:6,t:"Saul soube que Davi e os homens que estavam com ele tinham sido descobertos. Saul estava em Gabaá, sentado debaixo da tamargueira, no alto, com a lança na mão, e todos os seus servos estavam de pé à sua volta.",np:1},
{v:7,t:"Saul disse aos servos que o rodeavam: Ouvi, benjaminitas! Acaso o filho de Jessé vos dará a todos campos e vinhas, e fará de todos vós chefes de mil e chefes de cem,",n:"Saul fala aos da sua tribo: o reino tornou-se para ele um negócio de família e de clientela."},
{v:8,t:"para que todos vos tenhais conjurado contra mim? Ninguém me avisou de que o meu filho fez aliança com o filho de Jessé; ninguém de vós se compadece de mim, nem me avisa de que o meu filho incitou o meu servo contra mim, para me armar ciladas, como hoje se vê."},
{v:9,t:"Doeg, o edomita, que estava entre os servos de Saul, tomou a palavra e disse: Vi o filho de Jessé chegar a Nob, à casa de Aquimelec, filho de Aquitob;"},
{v:10,t:"ele consultou o Senhor por Davi, deu-lhe provisões e deu-lhe também a espada de Golias, o filisteu.",n:"Doeg acrescenta a consulta ao Senhor, que o capítulo anterior não menciona. O Salmo 52, segundo o título, visa este delator."},
{v:11,t:"O rei mandou chamar o sacerdote Aquimelec, filho de Aquitob, e toda a família de seu pai, os sacerdotes que estavam em Nob; e todos vieram ter com o rei.",np:1},
{v:12,t:"Saul disse: Ouve, filho de Aquitob! Ele respondeu: Aqui estou, meu senhor."},
{v:13,t:"Saul lhe disse: Por que conspirastes contra mim, tu e o filho de Jessé? Tu lhe deste pão e uma espada e consultaste a Deus por ele, para que ele se levantasse contra mim e me armasse ciladas, como hoje se vê."},
{v:14,t:"Aquimelec respondeu ao rei: Quem há, entre todos os teus servos, tão fiel como Davi, genro do rei, chefe da tua guarda pessoal e honrado em tua casa?"},
{v:15,t:"Foi hoje que comecei a consultar a Deus por ele? Longe de mim! Que o rei não impute tal coisa ao seu servo nem a toda a família de meu pai, porque o teu servo não sabia nada deste assunto, nem pouco nem muito."},
{v:16,t:"O rei disse: Morrerás, Aquimelec, tu e toda a família de teu pai."},
{v:17,t:"E o rei disse aos guardas que o rodeavam: Voltai-vos e matai os sacerdotes do Senhor, porque também eles estão do lado de Davi: sabiam que ele fugia e não me avisaram. Mas os servos do rei não quiseram levantar a mão contra os sacerdotes do Senhor.",n:"A recusa dos guardas mostra até onde chegou o desvario de Saul: nem os seus o seguem."},
{v:18,t:"Então o rei disse a Doeg: Volta-te tu e lança-te sobre os sacerdotes. Doeg, o edomita, voltou-se e lançou-se sobre os sacerdotes; e matou naquele dia oitenta e cinco homens que vestiam o efod de linho.",n:"Cumpre-se, pela mão de um estrangeiro, a sentença contra a casa de Heli (2,31-33)."},
{v:19,t:"E passou ao fio da espada Nob, a cidade dos sacerdotes: homens e mulheres, crianças e bebês de peito, bois, jumentos e ovelhas, ao fio da espada.",n:"Saul faz contra os sacerdotes do Senhor o extermínio que não quis fazer contra Amalec."},
{v:20,t:"Mas escapou um dos filhos de Aquimelec, filho de Aquitob, chamado Abiatar, que fugiu para junto de Davi",np:1},
{v:21,t:"e lhe contou que Saul tinha matado os sacerdotes do Senhor."},
{v:22,t:"Davi disse a Abiatar: Eu sabia, naquele dia, que Doeg, o edomita, estando ali, certamente avisaria Saul. Sou eu o culpado da morte de todos os da casa de teu pai."},
{v:23,t:"Fica comigo, não tenhas medo: quem procura a minha vida procura também a tua; comigo estarás em segurança.",n:"Abiatar será o sacerdote de Davi durante todo o seu reinado, até ser exilado por Salomão (1 Reis 2,26-27)."}
];

window.TEXTOS_SEED["1samuel"][23] = [
{s:"Davi salva Ceila"},
{v:1,t:"Informaram a Davi: Os filisteus estão atacando Ceila e saqueando as eiras.",n:"Ceila era uma cidade de Judá, na Sefelá. Saquear as eiras na época da colheita era roubar o pão do ano inteiro."},
{v:2,t:"Davi consultou o Senhor, dizendo: Devo ir e atacar esses filisteus? O Senhor respondeu a Davi: Vai, ataca os filisteus e salva Ceila."},
{v:3,t:"Mas os homens de Davi lhe disseram: Aqui em Judá já temos medo; quanto mais se formos a Ceila contra as tropas dos filisteus!"},
{v:4,t:"Davi consultou de novo o Senhor, e o Senhor lhe respondeu: Levanta-te e desce a Ceila, porque eu entregarei os filisteus nas tuas mãos."},
{v:5,t:"Davi foi a Ceila com os seus homens e combateu contra os filisteus; levou o seu gado e infligiu-lhes uma grande derrota. Assim Davi salvou os habitantes de Ceila."},
{v:6,t:"Quando Abiatar, filho de Aquimelec, fugiu para junto de Davi, desceu com ele a Ceila, levando consigo o efod.",n:"Davi tem agora consigo o sacerdote e o efod, pelo qual consulta a Deus; Saul, que matou os sacerdotes, ficou sem resposta."},
{s:"Davi escapa de Saul"},
{v:7,t:"Informaram a Saul que Davi tinha ido a Ceila, e Saul disse: Deus o entregou nas minhas mãos, porque ele se encerrou, entrando numa cidade com portas e ferrolhos.",np:1},
{v:8,t:"Saul convocou todo o povo para a guerra, para descer a Ceila e sitiar Davi e os seus homens."},
{v:9,t:"Quando Davi soube que Saul tramava secretamente o seu mal, disse ao sacerdote Abiatar: Traze o efod."},
{v:10,t:"E Davi disse: Senhor, Deus de Israel, o teu servo ouviu dizer que Saul se prepara para vir a Ceila, para destruir a cidade por minha causa."},
{v:11,t:"Os homens de Ceila me entregarão nas mãos dele? Saul descerá, como o teu servo ouviu dizer? Senhor, Deus de Israel, responde ao teu servo! O Senhor respondeu: Descerá."},
{v:12,t:"Davi perguntou: Os homens de Ceila me entregarão, a mim e aos meus homens, nas mãos de Saul? O Senhor respondeu: Entregarão.",n:"A ingratidão de Ceila, que Davi acabara de salvar, mostra o medo que Saul inspirava depois de Nob."},
{v:13,t:"Então Davi partiu com os seus homens, cerca de seiscentos; saíram de Ceila e andaram de um lugar para outro, sem rumo certo. Informaram a Saul que Davi tinha escapado de Ceila, e ele desistiu da expedição."},
{v:14,t:"Davi ficou no deserto, em lugares de difícil acesso, e morava na montanha, no deserto de Zif. Saul procurava-o todos os dias, mas Deus não o entregou nas suas mãos.",np:1},
{s:"Jônatas visita Davi"},
{v:15,t:"Davi soube que Saul tinha saído para lhe tirar a vida. Davi estava no deserto de Zif, em Horesa.",np:1},
{v:16,t:"Jônatas, filho de Saul, levantou-se, foi ter com Davi em Horesa e fortaleceu a sua confiança em Deus, dizendo-lhe:"},
{v:17,t:"Não tenhas medo, porque a mão de Saul, meu pai, não te alcançará; tu reinarás sobre Israel, e eu serei o segundo depois de ti; e Saul, meu pai, também o sabe.",n:"É o último encontro dos dois amigos. Jônatas renuncia ao trono com uma grandeza rara; não verá cumprir-se o que anuncia."},
{v:18,t:"Os dois fizeram aliança diante do Senhor. Davi ficou em Horesa, e Jônatas voltou para sua casa."},
{s:"Os zifeus denunciam Davi"},
{v:19,t:"Os zifeus subiram a Gabaá para dizer a Saul: Davi não está escondido entre nós, nos refúgios de Horesa, na colina de Haquila, ao sul do deserto?",np:1,n:"O título do Salmo 54 lembra esta traição."},
{v:20,t:"Agora, pois, ó rei, se desejas descer, desce; a nós caberá entregá-lo nas mãos do rei."},
{v:21,t:"Saul disse: Benditos sejais do Senhor, porque tivestes compaixão de mim!"},
{v:22,t:"Ide, pois, e tomai ainda mais precauções; informai-vos bem, examinai o lugar por onde ele anda e quem o viu ali, porque me disseram que ele é muito astuto."},
{v:23,t:"Examinai e descobri todos os esconderijos em que ele se abriga, e voltai a mim com informações seguras; então irei convosco. Se ele estiver na região, eu o buscarei por todos os clãs de Judá."},
{v:24,t:"Eles se levantaram e foram para Zif, adiante de Saul. Davi e os seus homens estavam no deserto de Maon, na Arabá, ao sul do deserto."},
{v:25,t:"Saul e os seus homens foram procurá-lo. Avisaram Davi, e ele desceu ao rochedo e ficou no deserto de Maon. Saul soube disso e perseguiu Davi no deserto de Maon."},
{v:26,t:"Saul caminhava por um lado da montanha, e Davi e os seus homens pelo outro lado; Davi apressava-se a fugir de Saul, enquanto Saul e os seus homens cercavam Davi e os seus homens, para prendê-los.",n:"Os dois grupos contornam a mesma montanha, cada um de um lado: Saul está a ponto de fechar o cerco."},
{v:27,t:"Mas chegou um mensageiro que disse a Saul: Vem depressa, porque os filisteus invadiram a terra!"},
{v:28,t:"Saul deixou de perseguir Davi e foi ao encontro dos filisteus. Por isso deram àquele lugar o nome de Rochedo da Separação.",n:"Os filisteus, sem saber, salvam Davi. O nome hebraico, Sela-Hamalecot, pode significar também rochedo das escapadas."}
];

window.TEXTOS_SEED["1samuel"][24] = [
{s:"Davi poupa Saul na caverna"},
{v:1,t:"Davi subiu dali e ficou nos refúgios de Engadi.",n:"Engadi é um oásis junto ao mar Morto, entre penhascos cheios de cavernas."},
{v:2,t:"Quando Saul voltou da perseguição aos filisteus, informaram-lhe: Davi está no deserto de Engadi.",np:1},
{v:3,t:"Saul tomou três mil homens escolhidos de todo o Israel e foi à procura de Davi e dos seus homens, até os Rochedos das Cabras Monteses."},
{v:4,t:"Chegou aos currais de ovelhas que havia junto do caminho. Havia ali uma caverna, e Saul entrou nela para fazer as suas necessidades; e Davi e os seus homens estavam escondidos no fundo da caverna."},
{v:5,t:"Os homens de Davi disseram-lhe: Eis o dia de que o Senhor te falou: Eu te entrego o teu inimigo, para que lhe faças o que te parecer bem. Davi levantou-se e, sem ser percebido, cortou a orla do manto de Saul."},
{v:6,t:"Mas depois o coração de Davi o acusou, por ter cortado a orla do manto de Saul,",n:"Cortar a orla do manto era como tocar na dignidade do rei: o manto representava a pessoa e o seu poder (15,27)."},
{v:7,t:"e ele disse aos seus homens: O Senhor me livre de fazer tal coisa ao meu senhor, ao ungido do Senhor, levantando a mão contra ele, porque é o ungido do Senhor.",n:"O ungido do Senhor é sagrado: Davi respeita em Saul a unção de Deus, ainda que o rei o persiga injustamente. Será também a sua proteção quando ele mesmo for rei."},
{v:8,t:"Com essas palavras Davi conteve os seus homens e não lhes permitiu lançar-se sobre Saul. Saul saiu da caverna e seguiu o seu caminho."},
{v:9,t:"Depois Davi também se levantou, saiu da caverna e gritou atrás de Saul: Ó rei, meu senhor! Saul olhou para trás, e Davi inclinou-se com o rosto em terra e prostrou-se,",np:1},
{v:10,t:"e disse a Saul: Por que dás ouvidos às palavras dos que dizem: Davi procura o teu mal?"},
{v:11,t:"Hoje os teus olhos viram que o Senhor te entregou hoje nas minhas mãos, na caverna. Disseram-me que te matasse, mas eu te poupei, pensando: Não levantarei a mão contra o meu senhor, porque ele é o ungido do Senhor"},
{v:12,t:"e meu pai. Olha, vê a orla do teu manto na minha mão: se cortei a orla do teu manto e não te matei, reconhece e vê que não há em mim maldade nem traição, e que não pequei contra ti; e tu andas à caça da minha vida, para tirá-la.",n:"E meu pai: a Nova Vulgata une estas palavras à frase anterior; no hebraico, começam uma nova frase: Meu pai, olha. Saul era sogro de Davi."},
{v:13,t:"O Senhor seja juiz entre mim e ti, e o Senhor me vingue de ti; mas a minha mão não se levantará contra ti."},
{v:14,t:"Como diz o antigo provérbio: Dos ímpios sai a impiedade; mas a minha mão não se levantará contra ti."},
{v:15,t:"Atrás de quem saiu o rei de Israel? Atrás de quem corres? Atrás de um cão morto, de uma pulga!",n:"Davi rebaixa-se a si mesmo para mostrar o absurdo da perseguição: o rei de Israel gasta as suas forças atrás de um nada."},
{v:16,t:"Que o Senhor seja juiz e julgue entre mim e ti; que ele veja, defenda a minha causa e me livre da tua mão."},
{v:17,t:"Quando Davi acabou de dizer estas palavras a Saul, Saul disse: É esta a tua voz, meu filho Davi? E Saul levantou a voz e chorou.",np:1},
{v:18,t:"E disse a Davi: Tu és mais justo do que eu, porque me fizeste o bem, e eu te paguei com o mal."},
{v:19,t:"Mostraste hoje o bem que me fizeste: o Senhor me entregou nas tuas mãos, e tu não me mataste."},
{v:20,t:"Quem, encontrando o seu inimigo, o deixa seguir o seu caminho em paz? Que o Senhor te recompense pelo que hoje fizeste por mim."},
{v:21,t:"Agora, pois, sei que certamente reinarás e que o reino de Israel será firme nas tuas mãos.",n:"O próprio Saul reconhece o que Jônatas já dissera (23,17)."},
{v:22,t:"Jura-me, pois, pelo Senhor que não exterminarás a minha descendência depois de mim, nem apagarás o meu nome da casa de meu pai."},
{v:23,t:"Davi jurou a Saul. Saul voltou para sua casa, e Davi e os seus homens subiram ao refúgio.",n:"Davi não se fia na emoção de Saul: volta ao refúgio."}
];

window.TEXTOS_SEED["1samuel"][25] = [
{s:"A morte de Samuel"},
{v:1,t:"Samuel morreu. Todo o Israel se reuniu e o chorou, e o sepultaram em sua casa, em Ramá. Davi levantou-se e desceu ao deserto de Maon.",n:"Deserto de Maon: assim a versão grega, que a Nova Vulgata segue; o hebraico diz deserto de Farã, muito mais ao sul."},
{s:"Davi, Nabal e Abigail"},
{v:2,t:"Havia em Maon um homem que tinha os seus bens em Carmel. Era um homem muito rico: tinha três mil ovelhas e mil cabras. Estava então em Carmel, tosquiando o seu rebanho.",np:1},
{v:3,t:"O homem chamava-se Nabal, e a sua mulher, Abigail. A mulher era muito sensata e bela; mas o marido era duro e de maus modos. Era da família de Caleb.",n:"Nabal quer dizer insensato. Caleb, o companheiro de Josué, tinha recebido Hebron e aquela região; o nome soa também como keleb, cão."},
{v:4,t:"Davi soube no deserto que Nabal estava tosquiando o seu rebanho,"},
{v:5,t:"e enviou dez rapazes, dizendo-lhes: Subi a Carmel, ide ter com Nabal e saudai-o em meu nome,",n:"A tosquia era tempo de festa e de fartura, em que se costumava ser generoso."},
{v:6,t:"e direis ao meu irmão: Paz a ti, paz à tua casa e paz a tudo o que é teu!"},
{v:7,t:"Ouvi dizer que tens tosquiadores. Os teus pastores estiveram conosco no deserto: nunca os molestamos, e nada lhes faltou do rebanho durante todo o tempo que estiveram conosco em Carmel.",n:"Davi e os seus homens protegiam os rebanhos contra os saqueadores do deserto; agora pedem a sua parte, como era costume."},
{v:8,t:"Pergunta aos teus servos, e eles te dirão. Que estes rapazes encontrem favor aos teus olhos, pois viemos num dia de festa. Dá aos teus servos e ao teu filho Davi o que tiveres à mão."},
{v:9,t:"Os rapazes de Davi chegaram, disseram a Nabal todas essas palavras em nome de Davi e ficaram esperando.",np:1},
{v:10,t:"Nabal respondeu aos servos de Davi: Quem é Davi? Quem é o filho de Jessé? Hoje em dia são muitos os escravos que fogem dos seus senhores."},
{v:11,t:"Hei de tomar o meu pão, a minha água e a carne que abati para os meus tosquiadores, e dá-los a homens que nem sei de onde vêm?"},
{v:12,t:"Os rapazes de Davi deram meia-volta, voltaram e contaram-lhe todas essas palavras."},
{v:13,t:"Então Davi disse aos seus homens: Cada um cinja a sua espada! Cada um cingiu a sua espada, e Davi também cingiu a sua; e cerca de quatrocentos homens subiram atrás de Davi, enquanto duzentos ficaram com as bagagens."},
{v:14,t:"Um dos servos avisou Abigail, mulher de Nabal, dizendo: Davi enviou mensageiros do deserto para saudar o nosso senhor, mas ele os destratou.",np:1},
{v:15,t:"No entanto, esses homens foram muito bons para nós e nunca nos molestaram; nada nos faltou durante todo o tempo que andamos com eles no deserto."},
{v:16,t:"Foram para nós como uma muralha, de noite e de dia, todo o tempo que apascentamos os rebanhos perto deles."},
{v:17,t:"Agora, pois, pensa bem e vê o que deves fazer, porque a desgraça está decidida contra o nosso senhor e contra toda a sua casa. E ele é tão perverso que ninguém lhe pode falar."},
{v:18,t:"Abigail apressou-se, tomou duzentos pães, dois odres de vinho, cinco carneiros preparados, cinco medidas de grão torrado, cem cachos de passas e duzentas tortas de figos secos, e carregou tudo em jumentos.",np:1},
{v:19,t:"E disse aos seus servos: Ide adiante de mim, e eu vos seguirei. Mas não disse nada a Nabal, seu marido."},
{v:20,t:"Montada no jumento, ela descia pela encosta encoberta do monte, e eis que Davi e os seus homens desciam ao seu encontro; e ela os encontrou."},
{v:21,t:"Davi tinha dito: Foi em vão que guardei no deserto tudo o que era desse homem, e nada se perdeu de tudo o que lhe pertencia; e ele me pagou o bem com o mal."},
{v:22,t:"Que Deus faça isto aos inimigos de Davi e mais aquilo, se até amanhã eu deixar com vida um só homem de tudo o que lhe pertence!",n:"Aos inimigos de Davi: os copistas acrescentaram estas palavras para que Davi não parecesse amaldiçoar a si mesmo; o texto original dizia provavelmente: que Deus faça isto a Davi."},
{v:23,t:"Quando Abigail viu Davi, desceu depressa do jumento, lançou-se com o rosto por terra diante de Davi e prostrou-se.",np:1},
{v:24,t:"E, caída aos seus pés, disse: Sobre mim, meu senhor, recaia a culpa! Permite que a tua serva fale aos teus ouvidos, e escuta as palavras da tua serva."},
{v:25,t:"Que o meu senhor não dê importância a esse homem perverso, Nabal, porque ele é como o seu nome: Nabal, o insensato, é o seu nome, e a insensatez está com ele. Eu, tua serva, não vi os rapazes que o meu senhor enviou."},
{v:26,t:"Agora, pois, meu senhor, pela vida do Senhor e pela tua vida: foi o Senhor que te impediu de derramar sangue e de fazer justiça pela tua própria mão. E agora, que sejam como Nabal os teus inimigos e os que procuram o mal do meu senhor.",n:"Abigail fala como profetisa: vê na sua própria intervenção a mão de Deus, que preserva Davi de manchar-se de sangue inocente."},
{v:27,t:"Aceita este presente que a tua serva trouxe ao meu senhor, e que seja dado aos rapazes que seguem o meu senhor."},
{v:28,t:"Perdoa a falta da tua serva. Certamente o Senhor fará ao meu senhor uma casa estável, porque o meu senhor combate as guerras do Senhor; e não se ache mal em ti em todos os dias da tua vida.",n:"Uma casa estável: Abigail antecipa a promessa que Natã fará a Davi (2 Samuel 7,16)."},
{v:29,t:"Se alguém se levantar para te perseguir e procurar a tua vida, a vida do meu senhor estará guardada no feixe dos vivos, junto do Senhor teu Deus; mas a vida dos teus inimigos, ele a lançará para longe, como a pedra da funda.",n:"O feixe dos vivos: imagem do embrulho em que se guardavam as coisas preciosas. A expressão passou para as inscrições dos túmulos judaicos, como prece pelos mortos. A funda lembra Golias."},
{v:30,t:"Quando o Senhor tiver feito ao meu senhor todo o bem que lhe prometeu e o tiver constituído chefe de Israel,"},
{v:31,t:"o meu senhor não terá o remorso nem o peso no coração de ter derramado sangue inocente e de se ter vingado por si mesmo. E, quando o Senhor tiver feito o bem ao meu senhor, lembra-te da tua serva."},
{v:32,t:"Davi disse a Abigail: Bendito seja o Senhor, Deus de Israel, que hoje te enviou ao meu encontro! Bendita a tua sensatez,",np:1},
{v:33,t:"e bendita sejas tu, que hoje me impediste de derramar sangue e de me vingar pela minha própria mão."},
{v:34,t:"Pois, pela vida do Senhor, Deus de Israel, que me impediu de te fazer mal: se não tivesses vindo depressa ao meu encontro, até o amanhecer não teria restado a Nabal um só homem."},
{v:35,t:"Davi aceitou das mãos dela o que ela lhe trouxera e disse-lhe: Volta em paz para tua casa. Vê: ouvi a tua voz e atendi o teu pedido."},
{v:36,t:"Abigail voltou para junto de Nabal, e eis que ele dava em casa um banquete, um banquete de rei. Nabal estava alegre, porque estava completamente embriagado; e ela não lhe disse nada, nem pouco nem muito, até o amanhecer.",np:1},
{v:37,t:"De manhã, quando passou a embriaguez de Nabal, sua mulher lhe contou tudo isso; e o seu coração desfaleceu dentro dele, e ele ficou como uma pedra.",n:"Talvez um ataque de apoplexia, provocado pela fúria ou pelo medo."},
{v:38,t:"Uns dez dias depois, o Senhor feriu Nabal, e ele morreu."},
{v:39,t:"Quando Davi soube que Nabal tinha morrido, disse: Bendito seja o Senhor, que defendeu a minha causa contra o ultraje de Nabal, preservou o seu servo do mal e fez recair sobre a cabeça de Nabal a sua maldade. Depois Davi mandou propor a Abigail que se tornasse sua mulher.",np:1},
{v:40,t:"Os servos de Davi foram ter com Abigail em Carmel e lhe disseram: Davi nos enviou a ti, para te tomar por mulher."},
{v:41,t:"Ela se levantou, prostrou-se com o rosto em terra e disse: A tua serva será uma escrava para lavar os pés dos servos do meu senhor."},
{v:42,t:"Abigail levantou-se depressa, montou num jumento e, acompanhada de cinco criadas, seguiu os mensageiros de Davi e tornou-se sua mulher."},
{v:43,t:"Davi também tinha tomado Aquinoam, de Jezrael; e ambas foram suas mulheres.",np:1},
{v:44,t:"Saul tinha dado sua filha Micol, mulher de Davi, a Falti, filho de Lais, que era de Galim.",n:"Casar a filha com outro era anular publicamente os laços de Davi com a casa real. Davi exigirá Micol de volta (2 Samuel 3,13-16)."}
];

window.TEXTOS_SEED["1samuel"][26] = [
{s:"Davi poupa Saul pela segunda vez"},
{v:1,t:"Os zifeus foram ter com Saul em Gabaá e disseram: Davi não está escondido na colina de Haquila, defronte do deserto?",n:"Esta narrativa é paralela à do capítulo 24: talvez duas versões do mesmo acontecimento, conservadas por tradições diferentes. O redator as mantém ambas: a magnanimidade de Davi repetida confirma a sua inocência."},
{v:2,t:"Saul levantou-se e desceu ao deserto de Zif, com três mil homens escolhidos de Israel, para procurar Davi no deserto de Zif."},
{v:3,t:"Saul acampou na colina de Haquila, defronte do deserto, junto ao caminho. Davi estava no deserto; e, vendo que Saul tinha vindo atrás dele ao deserto,"},
{v:4,t:"enviou espiões e soube que Saul tinha de fato chegado."},
{v:5,t:"Davi levantou-se e foi ao lugar onde Saul estava acampado. Viu o lugar onde dormiam Saul e Abner, filho de Ner, chefe do seu exército: Saul dormia no meio do acampamento, e o povo estava acampado ao seu redor.",np:1},
{v:6,t:"Davi perguntou a Aquimelec, o heteu, e a Abisai, filho de Sárvia, irmão de Joab: Quem descerá comigo ao acampamento, até Saul? Abisai respondeu: Eu descerei contigo.",n:"Sárvia era irmã de Davi (1 Crônicas 2,16): Joab, Abisai e Asael são sobrinhos do futuro rei."},
{v:7,t:"Davi e Abisai foram de noite até o povo, e eis que Saul estava deitado, dormindo no meio do acampamento, com a lança fincada na terra à cabeceira; Abner e o povo dormiam ao seu redor."},
{v:8,t:"Abisai disse a Davi: Deus entregou hoje o teu inimigo nas tuas mãos. Deixa-me cravá-lo na terra com a lança, de um só golpe; não será preciso o segundo."},
{v:9,t:"Mas Davi disse a Abisai: Não o mates! Quem poderá levantar a mão contra o ungido do Senhor e ficar impune?"},
{v:10,t:"E Davi acrescentou: Pela vida do Senhor, o próprio Senhor o ferirá: ou chegará o seu dia de morrer, ou descerá à batalha e perecerá."},
{v:11,t:"O Senhor me livre de levantar a mão contra o ungido do Senhor! Toma agora a lança que está à sua cabeceira e a bilha de água, e vamo-nos."},
{v:12,t:"Davi tomou a lança e a bilha de água que estavam à cabeceira de Saul, e eles se foram. Ninguém os viu, ninguém percebeu nada, ninguém acordou: todos dormiam, porque um sono profundo, enviado pelo Senhor, tinha caído sobre eles.",n:"O sono profundo é o mesmo que Deus fez cair sobre Adão (Gênesis 2,21): é Deus quem entrega Saul, e é Davi quem o poupa."},
{v:13,t:"Davi passou para o outro lado e ficou de pé no alto do monte, ao longe, havendo um grande espaço entre eles.",np:1},
{v:14,t:"E Davi gritou ao povo e a Abner, filho de Ner: Não respondes, Abner? Abner respondeu: Quem és tu, que gritas ao rei?"},
{v:15,t:"Davi disse a Abner: Não és tu um homem? Quem há como tu em Israel? Por que, então, não guardaste o rei, teu senhor? Pois um do povo entrou para matar o rei, teu senhor."},
{v:16,t:"Não é bom o que fizeste. Pela vida do Senhor, mereceis a morte, porque não guardastes o vosso senhor, o ungido do Senhor. Vê agora onde estão a lança do rei e a bilha de água que estavam à sua cabeceira.",n:"Davi zomba de Abner: o guarda do rei dormia, e é o inimigo que guarda a vida de Saul."},
{v:17,t:"Saul reconheceu a voz de Davi e disse: É esta a tua voz, meu filho Davi? Davi respondeu: É a minha voz, ó rei, meu senhor.",np:1},
{v:18,t:"E acrescentou: Por que o meu senhor persegue o seu servo? Que fiz eu? Que mal há na minha mão?"},
{v:19,t:"Agora, pois, que o rei, meu senhor, ouça as palavras do seu servo: se é o Senhor que te incita contra mim, que ele aspire o aroma de uma oferta; mas, se são os homens, malditos sejam diante do Senhor, porque hoje me expulsam, para que eu não tenha parte na herança do Senhor, dizendo: Vai servir a outros deuses!",n:"Aspire o aroma de uma oferta: que se deixe aplacar por um sacrifício. Ser expulso da terra de Israel era, para a mentalidade da época, ser obrigado a servir aos deuses do país estrangeiro."},
{v:20,t:"Que o meu sangue não seja derramado na terra, longe da presença do Senhor; porque o rei de Israel saiu à procura de uma pulga, como quem caça uma perdiz nos montes."},
{v:21,t:"Saul disse: Pequei. Volta, meu filho Davi; não te farei mais mal, porque hoje a minha vida foi preciosa aos teus olhos. Procedi como um insensato e errei gravemente.",np:1},
{v:22,t:"Davi respondeu: Aqui está a lança do rei; venha um dos rapazes buscá-la."},
{v:23,t:"O Senhor retribuirá a cada um segundo a sua justiça e a sua fidelidade: hoje o Senhor te entregou nas minhas mãos, e eu não quis levantar a mão contra o ungido do Senhor."},
{v:24,t:"Assim como hoje a tua vida foi preciosa aos meus olhos, assim seja preciosa a minha vida aos olhos do Senhor, e que ele me livre de toda angústia."},
{v:25,t:"Saul disse a Davi: Bendito sejas, meu filho Davi! Certamente farás grandes coisas e triunfarás. Davi seguiu o seu caminho, e Saul voltou para a sua casa.",n:"É o último encontro de Saul e Davi. As últimas palavras do rei ao seu rival são uma bênção."}
];

window.TEXTOS_SEED["1samuel"][27] = [
{s:"Davi entre os filisteus"},
{v:1,t:"Davi disse consigo: Um dia destes cairei nas mãos de Saul. Não é melhor fugir para a terra dos filisteus? Assim Saul desistirá de mim e deixará de me procurar em todo o território de Israel, e escaparei da sua mão."},
{v:2,t:"Davi levantou-se e passou, com os seiscentos homens que estavam com ele, para junto de Aquis, filho de Maoc, rei de Gat."},
{v:3,t:"Davi ficou em Gat com Aquis, ele e os seus homens, cada um com a sua família; Davi, com as suas duas mulheres, Aquinoam de Jezrael e Abigail de Carmel, mulher de Nabal."},
{v:4,t:"Informaram a Saul que Davi tinha fugido para Gat, e ele deixou de procurá-lo."},
{v:5,t:"Davi disse a Aquis: Se gozo do teu favor, que me seja dado um lugar numa das cidades do campo, para que eu more ali. Por que há de morar o teu servo contigo na cidade real?",np:1},
{v:6,t:"Naquele dia Aquis lhe deu Siceleg; por isso Siceleg pertence aos reis de Judá até o dia de hoje.",n:"Siceleg, no Negueb, tinha sido atribuída a Judá e a Simeão no tempo de Josué, mas estava em poder dos filisteus. Tornou-se propriedade da coroa de Judá."},
{v:7,t:"O tempo que Davi morou na terra dos filisteus foi de um ano e quatro meses."},
{v:8,t:"Davi e os seus homens subiam e faziam incursões contra os gessuritas, os gerzitas e os amalecitas; porque esses povos habitavam a região que vai desde Telém, na direção de Sur, até a terra do Egito.",np:1,n:"Desde Telém: assim a versão grega, que a Nova Vulgata segue; o hebraico diz desde sempre."},
{v:9,t:"Davi devastava a região e não deixava com vida nem homem nem mulher; e, tomando ovelhas, bois, jumentos, camelos e roupas, voltava para junto de Aquis."},
{v:10,t:"Aquis perguntava: Contra quem fizestes hoje a incursão? E Davi respondia: Contra o Negueb de Judá, ou contra o Negueb dos jerameelitas, ou contra o Negueb dos quenitas.",n:"Davi engana Aquis: diz atacar o território de Judá e dos clãs aliados de Judá, quando na verdade ataca os inimigos de Israel."},
{v:11,t:"Davi não deixava com vida nem homem nem mulher, para levá-los a Gat, pensando: Que eles não nos denunciem, dizendo: Assim fez Davi. Esse foi o seu modo de agir durante todo o tempo que morou na terra dos filisteus.",n:"A crueldade serve à mentira: não podia haver testemunhas. O narrador conta sem comentar; é o Davi dos anos de fuga, astuto e sem escrúpulos."},
{v:12,t:"E Aquis confiava em Davi, pensando: Ele se tornou odioso ao seu povo, a Israel; será meu servo para sempre."}
];
